+      server.notes.unshift(server.status === 'degraded' ? 'Latency elevated; incident opened.' : server.status === 'maintenance' ? 'Scheduled maintenance started.' : 'Host unreachable.');
+      if (server.notes.length > 8) server.notes.length = 8;
