    const t = tables[m[1]];
    if (!t) continue;
    const vals = splitArgs(m[2]).map(v => v.trim().replace(/^['"]|['"]$/g, ''));
    const row = {}; t.cols.forEach((c, i) => row[c] = vals[i]); t.rows.push(row);
