1492:       ]), time: Date.now(), world: game.worldMinutes });
1493:       if (thread.posts.length > 30) thread.posts.shift();
1494:     }
1495:   }
1496:   if (rng.chance(Math.min(.8, .012 * minutes))) {
1497:     const c = generateContract(game, rng);
1498:     if (c) events.push({ type: 'contract', text: `${c.id} ${c.title}` });
1499:   }
1500: 
1501:   // deadlines
