1595:     sites: game.sites.length, news: game.news.length, heat: game.player.heat,
1596:     owned: ownedServers(game).length
1597:   };
1598:   const steps = clamp(Math.ceil(worldMinutes / 30), 1, 320);
1599:   const chunk = Math.max(1, Math.round(worldMinutes / steps));
1600:   const events = [];
1601:   for (let i = 0; i < steps; i++) events.push(...tickWorld(game, chunk, { offline: true }));
1602:   const report = {
1603:     elapsedMs, realMinutes, worldMinutes,
1604:     moneyDelta: game.player.money - before.money,
1605:     newMail: game.mail.length - before.mail,
1606:     unread: unreadMail(game),
1607:     newContracts: game.contracts.filter(c => c.status === 'open').length - before.contracts,
1608:     newSites: game.sites.length - before.sites,
1609:     newNews: game.news.length - before.news,
1610:     heatDelta: Math.round(game.player.heat - before.heat),
1611:     events: events.filter(e => e.type !== 'summary'),
