   if (names.length===1) { input.value = names[0]+' '; }
   else if (names.length>1) { term.print(names.join('  '),'dim'); }
 } else {
   const slash = token.lastIndexOf('/');
   const dirPart = slash>=0 ? token.slice(0,slash+1) : '';
   const base = slash>=0 ? token.slice(slash+1) : token;
   const abs = resolvePath(term.cwd, dirPart || '.', HOME);
   const entries = listDir(term.remote?term.remote.server.fs:term.localFS, abs) || [];
   const matches = entries.filter(e=>e.name.startsWith(base));
   if (matches.length===1) {
     const m = matches[0];
     input.value = value.slice(0, value.length-token.length) + dirPart + m.name + (m.isDir?'/':' ');
