  const rect=win.el.getBoundingClientRect();
  const parent=layer.getBoundingClientRect();
  const left=rect.left-parent.left, top=rect.top-parent.top;
  const move = ev => {
    const nx = clamp(left + ev.clientX-startX, -rect.width+80, parent.width-80);
    const ny = clamp(top + ev.clientY-startY, 0, parent.height-32);
    win.el.style.left=nx+'px'; win.el.style.top=ny+'px';
  };
  const up=()=>{ document.removeEventListener('pointermove',move); document.removeEventListener('pointerup',up); };
  document.addEventListener('pointermove',move); document.addEventListener('pointerup',up);
  e.preventDefault();
}
