/* ---------------- Python subset ---------------- */
function runPython(ctx, source, filename) {
  const lines = source.replace(/\r/g, '').split('\n').map(l => l.replace(/\t/g, '    '));
  const vars = Object.create(null);
  vars.__name__ = '__main__';
  const out = [];
  let lineNo = 0;
  const builtins = {
    len: x => x?.length ?? 0,
    range: (a, b, c) => { if (b === undefined) { b = a; a = 0; } c = c || 1; const r = []; for (let i = a; c > 0 ? i < b : i > b; i += c) r.push(i); return r; },
    str: x => String(x), int: x => parseInt(x, 10), float: x => parseFloat(x),
    abs: Math.abs, round: Math.round, min: Math.min, max: Math.max, sum: arr => arr.reduce((a, b) => a + b, 0),
    sorted: arr => arr.slice().sort((a, b) => a - b), list: x => Array.from(x || []), bool: x => !!x,
    print: () => {}
  };
  function evalExpr(expr, scope) {
    let e = expr.trim();
    e = e.replace(/\bTrue\b/g, 'true').replace(/\bFalse\b/g, 'false').replace(/\bNone\b/g, 'null');
    e = e.replace(/\band\b/g, '&&').replace(/\bor\b/g, '||').replace(/\bnot\s+/g, '!');
    e = e.replace(/f(["'])(.*?)\1/g, (m, q, body) => {
      const pieces = body.replace(/\{([^}]+)\}/g, (mm, ex) => '${' + ex + '}');
      return '`' + pieces.replace(/`/g, '\\`') + '`';
    });
    const names = Object.keys(scope);
    const vals = names.map(n => scope[n]);
    const bnames = Object.keys(builtins);
    const bvals = bnames.map(n => builtins[n]);
    try {
      const fn = new Function(...names, ...bnames, `"use strict"; return (${e});`);
      return fn(...vals, ...bvals);
    } catch (err) {
      throw { python: true, message: err.message, expr: expr };
    }
  }
  function truthy(v) { return !!v && !(Array.isArray(v) && v.length === 0); }
  function execBlock(start, indent) {
    let i = start;
    while (i < lines.length) {
      const raw = lines[i];
      lineNo = i + 1;
      if (!raw.trim()) { i++; continue; }
      const ind = raw.match(/^\s*/)[0].length;
      if (ind < indent) return i;
      if (ind > indent) { throw { python: true, message: 'unexpected indent', line: i + 1 }; }
      let code = stripPyComment(raw.trim());
      if (!code) { i++; continue; }
      if (code.startsWith('#')) { i++; continue; }
      if (code.startsWith('import ') || code.startsWith('from ')) { i++; continue; }
      if (code.startsWith('def ')) {
        // Skip function definitions but record a simple callable later if trivial.
        const name = code.match(/^def\s+(\w+)/)?.[1];
        i++;
        let bodyStart = i;
        while (i < lines.length && (lines[i].trim() === '' || lines[i].match(/^\s*/)[0].length > indent)) i++;
        if (name) vars[name] = (...args) => { const local = Object.create(vars); return null; };
        continue;
      }
      if (code.startsWith('for ') && code.endsWith(':')) {
        const m = code.match(/^for\s+(\w+)\s+in\s+(.+):$/);
        if (!m) throw { python: true, message: 'invalid for statement', line: i + 1 };
        const iterable = evalExpr(m[2], vars);
        const arr = Array.isArray(iterable) ? iterable : typeof iterable === 'string' ? iterable.split('') : [];
        let bodyStart = i + 1;
        while (bodyStart < lines.length && (!lines[bodyStart].trim() || lines[bodyStart].match(/^\s*/)[0].length > indent)) bodyStart++;
        let j = bodyStart;
        while (j < lines.length && (lines[j].trim() === '' || lines[j].match(/^\s*/)[0].length > indent)) j++;
        for (const val of arr) {
          vars[m[1]] = val;
          execBlock(bodyStart, indent + 4);
        }
        i = j;
        continue;
      }
      if (code.startsWith('while ') && code.endsWith(':')) {
        const cond = code.slice(6, -1);
        let bodyStart = i + 1;
        let j = bodyStart;
        while (j < lines.length && (lines[j].trim() === '' || lines[j].match(/^\s*/)[0].length > indent)) j++;
        let guard = 0;
        while (evalExpr(cond, vars) && guard++ < 1000) execBlock(bodyStart, indent + 4);
        i = j;
        continue;
      }
      if (code.startsWith('if ') && code.endsWith(':')) {
        const cond = code.slice(3, -1);
        let bodyStart = i + 1;
        let j = bodyStart;
        while (j < lines.length && (lines[j].trim() === '' || lines[j].match(/^\s*/)[0].length > indent)) j++;
        if (truthy(evalExpr(cond, vars))) execBlock(bodyStart, indent + 4);
        // optional else / elif
        if (j < lines.length && lines[j].trim() === 'else:') {
          let elseStart = j + 1, k = elseStart;
          while (k < lines.length && (lines[k].trim() === '' || lines[k].match(/^\s*/)[0].length > indent)) k++;
          if (!truthy(evalExpr(cond, vars))) execBlock(elseStart, indent + 4);
          j = k;
        }
        i = j;
        continue;
      }
      if (code.startsWith('print')) {
        const m = code.match(/^print\s*\((.*)\)$/);
        if (!m) throw { python: true, message: 'invalid print call', line: i + 1 };
        const args = splitArgs(m[1]);
        const vals = args.map(a => evalExpr(a, vars));
        out.push(vals.map(v => v === null ? 'None' : typeof v === 'boolean' ? (v ? 'True' : 'False') : String(v)).join(' '));
        i++;
        continue;
      }
      if (code.startsWith('return')) { i++; continue; }
      const assign = code.match(/^([A-Za-z_]\w*)\s*(\+=|-=|\*=|\/=|=)\s*(.+)$/);
      if (assign) {
        const [, name, op, rhs] = assign;
        const val = evalExpr(rhs, vars);
        if (op === '=') vars[name] = val;
        else if (op === '+=') vars[name] = (vars[name] || 0) + val;
        else if (op === '-=') vars[name] = (vars[name] || 0) - val;
        else if (op === '*=') vars[name] = (vars[name] || 0) * val;
        else if (op === '/=') vars[name] = (vars[name] || 0) / val;
        i++;
        continue;
      }
      if (/^[A-Za-z_]\w*\s*\(.*\)$/.test(code)) { evalExpr(code, vars); i++; continue; }
      i++;
    }
    return i;
  }
  try {
    execBlock(0, 0);
    ctx.game.stats.codeLines += source.split('\n').length;
    if (out.length) ctx.print(out.join('\n'));
    else ctx.dim(`(${filename} produced no output)`);
    checkAchievements(ctx.game);
  } catch (err) {
    if (err.python) {
      ctx.err(`  File "${filename}", line ${err.line || lineNo}`);
      ctx.err(`    ${err.message}`);
      if (err.expr) ctx.dim(`    expression: ${err.expr}`);
    } else {
      ctx.err(`  File "${filename}", line ${lineNo}`);
      ctx.err(`    ${err.message}`);
    }
    ctx.print('Traceback (most recent call last):', 'dim');
    ctx.print('  [simulated runtime]', 'dim');
  }
}

