392:   const h = Math.max(30, canvas.height || 58);
393:   const dpr = Math.min(2, window.devicePixelRatio || 1);
394:   if (canvas.width !== Math.round(w * dpr)) canvas.width = Math.round(w * dpr);
395:   if (canvas.height !== Math.round(h * dpr)) canvas.height = Math.round(h * dpr);
396:   const ctx = canvas.getContext('2d');
