function kindClass(kind) {
  return kind === 'good' ? 'g' : kind === 'bad' || kind === 'legal' ? 'r' : kind === 'work' || kind === 'warn' ? 'a' : kind === 'news' ? 'b' : '';
}
function siteForServer(server) {
