  }
  if (c.status==='exited' && c.restartPolicy!=='no') { c.status='running'; c.restarts++; ... }
  if (c.status==='running') {
    c.uptime += minutes;
    c.requests += Math.round(rng.float(0.5,6)*minutes*(c.service==='web'?1:0.2));
    c.cpuUse = ...
    if (rng.chance(Math.min(.2, .0008*minutes))) { log... }
  }
}
