===================================================================
--- src/world.js
+++ src/world.js
@@ -9,8 +9,9 @@
 import {
   makeLocalFS, makeRemoteFS, writeFile, ensureDir, readFile, getNode, resolvePath, listDir,
   allFiles, HOME
 } from './vfs.js';
+import { buildSystems, ensureSystems, tickSystems } from './systems.js';

 export const SAVE_KEY = 'internet-persistent-world.v1';
