/* ---------------- cloud, containers, agents, organizations ---------------- */
function parseLongFlags(args, start = 0) {
  const flags = {}, rest = [];
  for (let i = start; i < args.length; i++) {
    const a = args[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      if (i + 1 < args.length && !args[i + 1].startsWith('--')) flags[key] = args[++i];
      else flags[key] = true;
    } else rest.push(a);
  }
  return { flags, rest };
}

COMMANDS.cloud = (ctx) => {
  const g = ctx.game;
  const sub = (ctx.args[0] || 'status').toLowerCase();
