75:     co.history = [{ world: game.worldMinutes, text: `${co.name} is operating in ${co.hq}.` }];
76: 
77:     const target = (co.employees || 10) * rng.float(1150, 2450) * (co.sector === 'legacy' ? .35 : 1);
78:     const count = clamp(Math.round((co.employees || 10) / 180) + 1, 1, 3);
79:     const templates = rng.picks(PRODUCT_TEMPLATES.filter(t => productFitsSector(t.category, co.sector)), count);
80:     const picks = templates.length ? templates : rng.picks(PRODUCT_TEMPLATES, count);
81:     for (let i = 0; i < picks.length; i++) {
82:       const t = picks[i];
83:       const price = Math.max(3, Math.round(t.price * rng.float(.7, 1.35)));
84:       const subs = Math.max(4, Math.round((target * (1 / picks.length)) / price * rng.float(.55, 1.15)));
85:       const product = {
86:         id: `prod-${String(game.seq.product++).padStart(4, '0')}`,
87:         companyId: co.id, name: `${co.name.split(' ')[0]} ${t.name}`,
88:         category: t.category, price, subscribers: subs,
89:         rating: rng.float(3.1, 4.8), growth: rng.float(-.0016, .0032),
90:         churn: rng.float(.0008, .004), status: 'live', desc: t.desc,
91:         launchedWorld: game.worldMinutes - rng.int(30, 900) * DAY,
92:         pendingRevenue: 0, pendingCost: 0
93:       };
94:       game.products.push(product);
95:       co.products.push(product.id);
96:     }
97: 
98:     const agentCount = co.employees > 500 ? 2 : 1;
99:     for (let i = 0; i < agentCount; i++) {
100:       const role = pickRoleForSector(rng, co.sector);
101:       const model = pickModelForCompany(rng, co);
102:       const name = agentName(rng, usedNames, co);
103:       game.agents.push(makeAgent(game, {
104:         name, ownerType: 'company', ownerId: co.id, ownerName: co.name,
105:         roleId: role.id, modelId: model.id, serverId: null,
106:         budget: Math.round(rng.float(180, 4200)), efficiency: rng.float(.84, 1.14),
107:         tasksDone: rng.int(12, 1400), createdAt: Date.now() - rng.int(20, 500) * 86400000
108:       }));
109:     }
110:   }
111: 
112:   for (let i = 0; i < 4; i++) {
113:     const role = rng.pick(AGENT_ROLES);
114:     const model = rng.pick(AGENT_MODELS);
115:     game.agents.push(makeAgent(game, {
116:       name: agentName(rng, usedNames, null), ownerType: 'independent', ownerId: null,
117:       ownerName: 'independent operator', roleId: role.id, modelId: model.id,
118:       budget: Math.round(rng.float(20, 300)), efficiency: rng.float(.7, 1.1),
119:       tasksDone: rng.int(3, 260), createdAt: Date.now() - rng.int(5, 240) * 86400000
120:     }));
121:   }
122:   return game;
123: }
