125: function productFitsSector(category, sector) {
126:   if (sector === 'cloud' || sector === 'hosting' || sector === 'infrastructure') return ['hosting','monitoring','dns','devtools'].includes(category);
127:   if (sector === 'security') return ['security','monitoring','devtools'].includes(category);
128:   if (sector === 'software' || sector === 'research') return ['devtools','ai','data','observability'].includes(category);
129:   if (sector === 'media') return ['data','messaging'].includes(category);
130:   if (sector === 'commerce') return ['messaging','hosting','data'].includes(category);
131:   return true;
132: }
133: function pickRoleForSector(rng, sector) {
134:   const map = {
135:     security: ['security','monitor'], cloud: ['monitor','support'], hosting: ['monitor','support'],
136:     software: ['developer','support'], research: ['research','analyst'], media: ['research','support'],
137:     commerce: ['support','sales'], finance: ['analyst','security'], government: ['security','analyst'],
138:     community: ['monitor','support'], consulting: ['analyst','security'], legacy: ['monitor','support'],
139:     infrastructure: ['monitor','security'], logistics: ['analyst','monitor'], manufacturing: ['monitor','support'],
140:     design: ['support','research'], data: ['analyst','research']
141:   };
142:   const ids = map[sector] || ['support','monitor'];
143:   return AGENT_ROLES.find(r => r.id === rng.pick(ids)) || rng.pick(AGENT_ROLES);
144: }
145: function pickModelForCompany(rng, co) {
146:   if (co.sector === 'community' || co.employees < 30) return rng.chance(.65) ? AGENT_MODELS.find(m => m.id === 'local-7b') : AGENT_MODELS.find(m => m.id === 'kestrel-mini');
147:   if (co.sector === 'security') return rng.chance(.7) ? AGENT_MODELS.find(m => m.id === 'vanta-guard') : AGENT_MODELS.find(m => m.id === 'atlas-reason');
148:   if (co.sector === 'research' || co.sector === 'data') return rng.chance(.55) ? AGENT_MODELS.find(m => m.id === 'atlas-reason') : AGENT_MODELS.find(m => m.id === 'nimbus-3');
149:   return rng.chance(.55) ? AGENT_MODELS.find(m => m.id === 'nimbus-3') : AGENT_MODELS.find(m => m.id === 'kestrel-mini');
150: }
151: function agentName(rng, used, co) {
152:   for (let i = 0; i < 40; i++) {
153:     const base = rng.pick(AGENT_NAMES);
154:     const name = `${base}-${rng.int(2, 99)}`;
155:     if (!used.has(name)) { used.add(name); return name; }
156:   }
157:   return `agent-${rng.hex(4)}`;
158: }
159: function makeAgent(game, opts) {
160:   const role = AGENT_ROLES.find(r => r.id === opts.roleId) || AGENT_ROLES[0];
161:   const model = AGENT_MODELS.find(m => m.id === opts.modelId) || AGENT_MODELS[0];
