165:     ownerName: opts.ownerName || 'independent', roleId: role.id, modelId: model.id,
166:     status: 'active', serverId: opts.serverId || null, siteId: opts.siteId || null,
167:     budget: opts.budget ?? 100, spend: 0, tasksDone: opts.tasksDone || 0,
168:     efficiency: opts.efficiency || 1, pendingRevenue: 0, pendingCost: 0,
169:     createdAt: opts.createdAt || Date.now(), lastTaskWorld: game.worldMinutes,
170:     memory: [{ world: game.worldMinutes, text: `Started as ${role.name} using ${model.name}.` }],
171:     capabilities: role.id === 'developer' ? ['read:code','write:code','run:tests'] :
172:       role.id === 'security' ? ['read:logs','read:policy','open:incident'] :
173:       role.id === 'support' ? ['read:tickets','draft:reply','escalate'] :
174:       role.id === 'monitor' ? ['read:metrics','read:logs','open:incident'] :
