237: export function runContainer(game, opts) {
238:   const server = game.servers.find(s => s.id === opts.serverId);
239:   if (!server) return { ok: false, error: 'No host selected.' };
240:   if (!server.owned) return { ok: false, error: 'That host is not yours.' };
241:   if (server.status === 'offline') return { ok: false, error: `${server.host} is offline.` };
242:   const image = imageInfo(opts.image);
243:   if (!image) return { ok: false, error: `Unable to find image '${opts.image}' locally.` };
244:   if (!game.cloud.images.includes(image.name)) game.cloud.images.push(image.name);
245:   const running = game.cloud.containers.filter(c => c.serverId === server.id && c.status === 'running');
246:   const usedRam = running.reduce((s, c) => s + (c.ram || 0), 0);
247:   if (usedRam + image.ram > server.ram) return { ok: false, error: `Host memory exhausted (${usedRam.toFixed(1)}/${server.ram} GB in use).` };
248:   const id = `ctr-${String(game.seq.container++).padStart(5, '0')}`;
249:   const name = (opts.name || `${image.service}-${id.slice(-4)}`).replace(/[^a-zA-Z0-9_.-]/g, '-');
250:   if (game.cloud.containers.some(c => c.name === name)) return { ok: false, error: `Conflict. The container name "/${name}" is already in use.` };
251:   const container = {
252:     id, name, image: image.name, service: image.service, serverId: server.id,
253:     port: opts.port || image.port, status: 'running', restartPolicy: opts.restart || 'always',
254:     ram: image.ram, cpu: image.cpu, requests: 0, revenue: 0, uptime: 0, restarts: 0,
255:     createdWorld: game.worldMinutes, createdAt: Date.now(), env: opts.env || [],
256:     logs: [`${new Date().toISOString()} starting ${image.name}`]
257:   };
258:   game.cloud.containers.push(container);
259:   server.tags = [...new Set([...server.tags, image.service])];
260:   return { ok: true, container, server, image };
261: }
