304: export function applyWorkload(game, cluster, manifest) {
305:   const name = manifest.name || manifest.metadata?.name;
306:   const imageName = manifest.image;
307:   if (!name) return { ok: false, error: 'manifest has no metadata.name' };
308:   const image = imageInfo(imageName);
