312:   if (w) { w.image = image.name; w.replicas = replicas; }
313:   else {
314:     w = { name, kind: manifest.kind || 'Deployment', image: image.name, replicas, service: image.service, port: image.port, running: replicas, restarts: 0, createdWorld: game.worldMinutes };
315:     cluster.workloads.push(w);
