628:   el.querySelector('[data-win="min"]').addEventListener('click', () => minimizeWindow(win));
629:   el.querySelector('[data-win="max"]').addEventListener('click', () => toggleMax(win));
630:   el.querySelector('[data-win="close"]').addEventListener('click', () => closeWindow(win));
631:   el.querySelector('.resize-handle').addEventListener('pointerdown', e => {
632:     if (window.innerWidth <= 860 || el.dataset.max === '1') return;
