643: function focusWindow(win) {
644:   if (!win || !app.windows.has(win.kind)) return;
645:   win.el.style.zIndex = String(++app.zTop);
646:   for (const w of app.windows.values()) w.el.classList.toggle('focused', w === win);
647:   app.focused = win.kind;
648:   updateDock();
649: }
