651: function minimizeWindow(win) {
652:   win.minimized = true;
653:   win.el.classList.add('minimized');
654:   if (app.focused === win.kind) {
655:     const next = [...app.windows.values()].filter(w => !w.minimized).sort((a, b) => Number(b.el.style.zIndex) - Number(a.el.style.zIndex))[0];
656:     if (next) focusWindow(next); else app.focused = null;
657:   }
658:   updateDock();
659: }
660: 
661: function closeWindow(win) {
662:   if (win.onClose && win.onClose() === false) return;
663:   if (win.cleanup) safe(win.cleanup);
664:   win.el.remove();
665:   app.windows.delete(win.kind);
666:   if (app.focused === win.kind) {
667:     app.focused = null;
668:     const next = [...app.windows.values()].filter(w => !w.minimized).sort((a, b) => Number(b.el.style.zIndex) - Number(a.el.style.zIndex))[0];
669:     if (next) focusWindow(next);
670:   }
671:   updateDock();
672: }
