674: function toggleMax(win) {
675:   const el = win.el;
676:   if (el.dataset.max === '1') {
677:     const r = win.prevRect || {};
678:     el.style.left = r.left || '24px';
679:     el.style.top = r.top || '20px';
680:     el.style.width = r.width || `${WINDOW_META[win.kind].w}px`;
681:     el.style.height = r.height || `${WINDOW_META[win.kind].h}px`;
682:     el.dataset.max = '0';
683:   } else {
684:     win.prevRect = { left: el.style.left, top: el.style.top, width: el.style.width, height: el.style.height };
685:     el.style.left = '8px';
686:     el.style.top = '8px';
687:     el.style.width = 'calc(100% - 16px)';
688:     el.style.height = 'calc(100% - 16px)';
689:     el.dataset.max = '1';
690:   }
691:   if (win.render) safe(() => win.render());
692: }
