870:   for (const line of lines) {
871:     const div = document.createElement('div');
872:     div.className = `tline${cls ? ' ' + cls : ''}`;
873:     div.textContent = line;
874:     scroll.appendChild(div);
875:   }
876:   while (scroll.children.length > 2200) scroll.firstElementChild.remove();
877:   if (nearBottom) scroll.scrollTop = scroll.scrollHeight;
878: }
