944: function completeInput(term) {
945:   const input = term.input;
946:   const value = input.value;
947:   const parts = value.split(/\s+/);
948:   const token = parts[parts.length - 1] || '';
949:   const atStart = parts.length === 1;
950:   let matches = [];
951:   if (atStart) {
952:     matches = commandNames().filter(c => c.startsWith(token));
953:   } else {
954:     const slash = token.lastIndexOf('/');
955:     const dirPart = slash >= 0 ? token.slice(0, slash + 1) : '';
956:     const base = slash >= 0 ? token.slice(slash + 1) : token;
957:     const abs = resolvePath(term.cwd, dirPart || '.', HOME);
958:     const entries = listDir(term.remote ? term.remote.server.fs : term.localFS, abs) || [];
959:     matches = entries.filter(e => e.name.startsWith(base)).map(e => dirPart + e.name + (e.isDir ? '/' : ''));
960:   }
961:   if (!matches.length) return;
962:   if (matches.length === 1) {
963:     parts[parts.length - 1] = matches[0];
964:     input.value = parts.join(' ') + (matches[0].endsWith('/') ? '' : ' ');
965:     return;
966:   }
967:   appendTermLine(term.scroll, matches.join('   '), 'dim');
968:   term.scroll.scrollTop = term.scroll.scrollHeight;
969: }
