500: function tickLoop() {
501:   if (!app.game) return;
502:   const now = Date.now();
503:   let mins = 1;
504:   if (now - app.lastTick > 5000) mins = Math.min(120, Math.round((now - app.lastTick) / 2000));
505:   app.lastTick = now;
506:   app.tickNo++;
507:   try { tickWorld(app.game, mins); } catch (e) { console.error('tick failed', e); }
508:   trimWorld();
509: 
510:   const g = app.game;
511:   const unread = unreadMail(g);
512:   if (unread > app.lastUnread) {
513:     const latest = [...g.mail].reverse().find(m => !m.outbound && !m.read);
514:     if (latest) toast('New mail', `@${latest.from} — ${latest.subject}`, 'b');
515:   }
516:   app.lastUnread = unread;
517: 
518:   const newAch = Object.keys(g.achievements).filter(id => !app.knownAch.has(id));
519:   for (const id of newAch) {
520:     const a = ACHIEVEMENTS.find(x => x.id === id);
521:     if (a) toast('Achievement unlocked', a.name, 'g');
522:     app.knownAch.add(id);
523:   }
524:   if (g.legal.length > app.lastLegal) {
525:     const ev = g.legal[g.legal.length - 1];
526:     if (ev) toast('Enforcement notice', `${fmtMoney(ev.fine)} fine — ${ev.reason}`, 'r');
527:     app.lastLegal = g.legal.length;
528:   }
529: 
530:   updateAll();
531:   if (app.tickNo % 3 === 0) softRefresh();
532:   if (app.tickNo % 9 === 0) saveGame(false);
533: }
