694: function startDrag(win, e) {
695:   if (e.button !== 0) return;
696:   const startX = e.clientX, startY = e.clientY;
697:   const el = win.el;
698:   const parent = layer.getBoundingClientRect();
699:   const left = el.offsetLeft, top = el.offsetTop;
700:   const width = el.offsetWidth;
701:   const move = ev => {
702:     el.style.left = `${clamp(left + ev.clientX - startX, -width + 90, parent.width - 90)}px`;
703:     el.style.top = `${clamp(top + ev.clientY - startY, 0, parent.height - 34)}px`;
704:   };
705:   const up = () => {
706:     document.removeEventListener('pointermove', move);
707:     document.removeEventListener('pointerup', up);
708:   };
709:   document.addEventListener('pointermove', move);
710:   document.addEventListener('pointerup', up);
711:   e.preventDefault();
712: }
