714: function startResize(win, e) {
715:   if (e.button !== 0) return;
716:   const startX = e.clientX, startY = e.clientY;
717:   const el = win.el;
718:   const parent = layer.getBoundingClientRect();
719:   const w0 = el.offsetWidth, h0 = el.offsetHeight;
720:   const move = ev => {
721:     el.style.width = `${clamp(w0 + ev.clientX - startX, 320, parent.width - el.offsetLeft - 4)}px`;
722:     el.style.height = `${clamp(h0 + ev.clientY - startY, 190, parent.height - el.offsetTop - 4)}px`;
723:   };
724:   const up = () => {
725:     document.removeEventListener('pointermove', move);
726:     document.removeEventListener('pointerup', up);
727:     if (win.render) safe(() => win.render());
728:   };
729:   document.addEventListener('pointermove', move);
730:   document.addEventListener('pointerup', up);
731:   e.preventDefault();
732: }
