916: async function submitLine(term, line) {
917:   term.queue.push(String(line ?? ''));
918:   if (term.busy) return;
919:   term.busy = true;
920:   if (term.input) term.input.disabled = true;
921:   while (term.queue.length) {
922:     const current = term.queue.shift();
923:     const mask = term.pending?.kind === 'ssh-password';
924:     appendEcho(term, current, mask);
925:     try {
926:       await execute(app, term, current);
927:     } catch (e) {
928:       console.error(e);
929:       term.print(`internal simulation error: ${e.message}`, 'err');
930:     }
931:     term.histIndex = term.history.length;
932:     const win = app.windows.get('terminal');
933:     if (win) updateTerminalChrome(win);
934:     if (term.input) term.input.value = '';
935:   }
936:   term.busy = false;
937:   if (term.input) {
938:     term.input.disabled = false;
939:     term.input.focus();
940:     term.scroll.scrollTop = term.scroll.scrollHeight;
941:   }
942: }
