1148: export function addMoney(game, amount, memo) {
1149:   amount = Math.round(amount);
1150:   game.player.money += amount;
1151:   if (amount > 0) game.stats.earned += amount;
1152:   else game.stats.spent += Math.abs(amount);
1153:   game.player.transactions.unshift({ time: Date.now(), amount, memo, balance: game.player.money });
1154:   if (game.player.transactions.length > 120) game.player.transactions.length = 120;
1155:   return game.player.money;
