1161: export function addHeat(game, amount, reason) {
1162:   let a = amount;
1163:   if (game.player.inventory.proxy > 0) a *= .68;
1164:   if (game.player.inventory.vpn > 0) a *= .85;
1165:   game.player.heat = clamp(game.player.heat + a, 0, 100);
