1172: export function investigate(game, reason = 'anomalous activity') {
1173:   const rng = makeRng((game.seed ^ game.worldMinutes ^ 0x9e37) >>> 0);
1174:   const fine = Math.min(Math.max(120, Math.round(game.player.money * .18)), 4200);
1175:   game.player.money = Math.max(0, game.player.money - fine);
1176:   game.player.heat = clamp(game.player.heat - 42, 0, 100);
1177:   game.player.reputation = clamp(game.player.reputation - rng.int(3, 9), 0, 100);
