1179:   game.legal.push(event);
1180:   addMail(game, {
1181:     from: 'notice', subject: 'Enforcement notice / trace resolution',
1182:     body: `An investigation into ${reason} has been resolved administratively.\n\nFine: ${fmtMoney(fine)}\nCase: CN-${rng.int(10000, 99999)}\n\nThe network regulator reminds all operators that persistent access is not consent. Further findings may result in suspension of network privileges.\n\n— CyberNet Authority`,
1183:     npcId: null
1184:   });
1185:   addFeed(game, `Investigation resolved: ${fmtMoney(fine)} fine and reputation loss.`, 'bad');
1186:   return event;
1187: }
1188: export function checkAchievements(game, silent = false) {
1189:   const p = game.player;
1190:   const owned = ownedServers(game).length;
1191:   const partners = new Set(game.mail.filter(m => !m.outbound).map(m => m.from));
1192:   const conditions = {
1193:     boot: true,
1194:     scan: game.stats.scans >= 1,
1195:     shell: game.stats.logins >= 1,
1196:     contract: game.stats.contracts >= 1,
1197:     deploy: game.stats.deploys >= 1,
1198:     paid: game.stats.earned >= 1000,
1199:     patch: game.stats.patches >= 1,
1200:     reputation: p.reputation >= 50,
1201:     network: owned >= 3,
1202:     clean: game.stats.contracts >= 1 && p.heat <= 0,
1203:     reader: partners.size >= 5,
1204:     news: game.stats.newsRead >= 10
1205:   };
1206:   const unlocked = [];
1207:   for (const a of ACHIEVEMENTS) {
1208:     if (!conditions[a.id] || game.achievements[a.id]) continue;
1209:     game.achievements[a.id] = Date.now();
1210:     p.achievements[a.id] = true;
1211:     unlocked.push(a);
1212:     if (!silent) addFeed(game, `Achievement unlocked — ${a.name}`, 'good');
1213:   }
1214:   return unlocked;
1215: }
