1225: export function objectiveSatisfied(game, contract) {
1226:   const o = contract.objective;
1227:   if (!o) return false;
1228:   if (o.type === 'scan') return !!game.flags.scanned[o.target];
1229:   if (o.type === 'audit') return !!game.flags.audited[o.target];
1230:   if (o.type === 'patch') return !!game.flags.patched[o.target];
1231:   if (o.type === 'exploit') return !!game.flags.exploited[o.target];
1232:   if (o.type === 'deploy') return game.stats.deploys > 0 || playerSites(game).length > 0;
1233:   if (o.type === 'code') {
1234:     const path = o.path?.startsWith('/') ? o.path : resolvePath(HOME, o.path || '');
1235:     const node = getNode(game.fs, path);
1236:     if (!node || node.type !== 'file') return false;
1237:     return node.content.trim().split('\n').length >= (o.minLines || 4);
1238:   }
1239:   return false;
1240: }
1241: export function acceptContract(game, contract) {
1242:   if (!contract) return { ok: false, error: 'No such contract.' };
1243:   if (contract.status !== 'open') return { ok: false, error: `Contract is ${contract.status}.` };
1244:   contract.status = 'active';
1245:   contract.acceptedWorld = game.worldMinutes;
1246:   const npc = game.npcs.find(n => n.id === contract.clientId);
1247:   if (npc) { game.player.relations[npc.handle] = (game.player.relations[npc.handle] || 0) + 2; npc.sent++; }
1248:   addFeed(game, `Accepted ${contract.id}: ${contract.title}`, 'work');
1249:   return { ok: true, contract };
1250: }
1251: export function submitContract(game, contract) {
1252:   if (!contract) return { ok: false, error: 'No such contract.' };
1253:   if (contract.status !== 'active') return { ok: false, error: `Contract is ${contract.status}.` };
1254:   if (!objectiveSatisfied(game, contract)) return { ok: false, error: 'Objective not yet satisfied. ' + (contract.objective.hint || '') };
1255:   contract.status = 'done';
1256:   contract.deliveredWorld = game.worldMinutes;
1257:   game.stats.contracts++;
1258:   game.player.contractsDone++;
1259:   const pay = contract.pay + (contract.bonus || 0);
1260:   addMoney(game, pay, `contract ${contract.id}`);
1261:   const rep = clamp(2 + contract.difficulty, 2, 9);
1262:   awardReputation(game, rep, `delivered ${contract.id}`);
1263:   const npc = game.npcs.find(n => n.id === contract.clientId);
1264:   if (npc) {
1265:     game.player.relations[npc.handle] = (game.player.relations[npc.handle] || 0) + 6;
1266:     npc.received++;
1267:     addMail(game, {
1268:       from: npc.handle, subject: `re: ${contract.title}`,
1269:       body: `Payment sent for ${contract.id}. ${['Clean work.','Received. Thanks.','Delivered as described.','Good. I will keep you in mind.','That is exactly what I needed.'][contract.difficulty % 5]}\n\n— ${npc.name}`,
1270:       npcId: npc.id
1271:     });
1272:   }
1273:   addFeed(game, `Contract delivered: ${contract.id} — ${fmtMoney(pay)}`, 'good');
1274:   checkAchievements(game);
1275:   return { ok: true, pay, rep };
1276: }
1277: export function generateContract(game, rng = null) {
1278:   rng = rng || makeRng((game.seed ^ game.worldMinutes ^ 0x51ed) >>> 0);
1279:   const t = rng.pick(CONTRACT_TEMPLATES);
1280:   const candidates = game.servers.filter(s => s.status === 'online' && s.host !== 'cybernet' && !s.owned);
1281:   if (!candidates.length) return null;
1282:   const target = rng.pick(candidates);
1283:   const client = rng.pick(game.npcs);
1284:   const extra = t.type === 'code' ? {
1285:     path: `/home/operator/projects/${rng.pick(['tool','site','monitor','report','client'])}.${t.tags.includes('web') ? 'html' : 'py'}`,
1286:     minLines: rng.int(5, 9)
1287:   } : {};
1288:   const objective = objectiveFor(t.type, target, extra);
1289:   const contract = {
1290:     id: `C-${game.seq.contract++}`, title: t.title, desc: t.desc,
1291:     clientId: client.id, clientHandle: client.handle, companyId: client.companyId,
1292:     pay: Math.round((t.base + rng.int(-50, 150)) * (1 + t.difficulty * .07)),
1293:     difficulty: t.difficulty, tags: t.tags, status: 'open', objective, progress: 0,
1294:     createdWorld: game.worldMinutes, acceptedWorld: null, deliveredWorld: null,
1295:     deadlineWorld: game.worldMinutes + (t.difficulty + 3) * MINUTES_PER_DAY,
1296:     requirements: `Deliver: ${objective.label}`, bonus: 0, escrow: 0
1297:   };
1298:   game.contracts.push(contract);
1299:   addFeed(game, `New contract posted: ${contract.title} (${fmtMoney(contract.pay)})`, 'work');
1300:   return contract;
1301: }
