1306: export function buyShopItem(game, item) {
1307:   if (!item) return { ok: false, error: 'Unknown item.' };
1308:   if (game.player.money < item.price) return { ok: false, error: `Insufficient funds. Need ${fmtMoney(item.price)}.` };
1309:   if (item.id === 'domain') return { ok: false, error: 'Register a domain with: buy domain <name>' };
1310:   addMoney(game, -item.price, `purchase ${item.name}`);
1311:   game.stats.purchases++;
1312:   if (item.kind === 'infra' && item.server) {
1313:     const server = createOwnedServer(game, item);
1314:     addFeed(game, `Provisioned ${item.name} at ${server.ip}`, 'good');
1315:     return { ok: true, server, item };
1316:   }
1317:   if (item.id === 'course') {
1318:     game.player.bonusSkill = (game.player.bonusSkill || 0) + 1;
1319:     addFeed(game, 'Completed the offensive lab. Skill increased.', 'good');
1320:     updateDerived(game);
1321:     return { ok: true, item };
1322:   }
1323:   if (item.id === 'ids') {
1324:     const owned = ownedServers(game);
1325:     if (owned.length) { owned[0].security = clamp(owned[0].security + 12, 0, 99); owned[0].tags.push('ids'); }
1326:     else game.player.inventory.ids++;
1327:     addFeed(game, 'IDS appliance installed.', 'good');
1328:     return { ok: true, item };
1329:   }
1330:   game.player.inventory[item.id] = (game.player.inventory[item.id] || 0) + 1;
1331:   addFeed(game, `Purchased ${item.name}.`, 'info');
1332:   return { ok: true, item };
1333: }
1334: export function createOwnedServer(game, item) {
1335:   const rng = makeRng((game.seed ^ game.seq.server ^ 0x77aa) >>> 0);
1336:   const id = `srv-owned-${String(game.seq.server++).padStart(3, '0')}`;
1337:   const host = `node-${rng.int(100, 999)}.operator.host`;
1338:   const ip = `198.51.100.${rng.int(220, 250)}`;
1339:   const server = makeServer(rng, {
1340:     id, seq: game.seq.server, ip, host, domain: host, org: 'operator', role: 'personal node',
1341:     os: 'Debian GNU/Linux 12 (bookworm)', security: 54, ports: [22, 80, 443],
1342:     user: 'operator', owned: true, ownerId: 'player', status: 'online',
1343:     tags: ['owned','web'], motd: 'Your node. Keep it patched.\n',
1344:     webroot: '<html><body><h1>It works.</h1><p>Your first node is online.</p></body></html>'
1345:   });
1346:   server.plan = item.id === 'vps-dedicated' ? 'dedicated' : item.id === 'vps-std' ? 'standard' : 'micro';
1347:   server.monthly = item.price;
1348:   server.cpu = item.server.cpu; server.ram = item.server.ram; server.disk = item.server.disk;
1349:   server.createdWorld = game.worldMinutes;
1350:   game.servers.push(server);
1351:   return server;
1352: }
1353: export function registerDomain(game, name) {
1354:   let domain = String(name || '').toLowerCase().trim();
1355:   if (!/^[a-z0-9][a-z0-9.-]*\.[a-z]{2,}$/.test(domain)) return { ok: false, error: 'Invalid domain name. Use something like quietfield.net.' };
1356:   if (game.sites.some(s => s.domain === domain)) return { ok: false, error: 'Domain is already registered.' };
1357:   if (game.player.money < 18) return { ok: false, error: 'Insufficient funds. Domain registration costs $18.' };
1358:   addMoney(game, -18, `domain ${domain}`);
