505: function buildServers(game, rng) {
506:   const usedIps = new Set();
507:   const usedDomains = new Set();
508:   const coByName = new Map(game.companies.map(c => [c.name, c]));
509:   const npcByCompany = new Map();
510:   for (const n of game.npcs) if (n.companyId) { if (!npcByCompany.has(n.companyId)) npcByCompany.set(n.companyId, []); npcByCompany.get(n.companyId).push(n); }
511: 
512:   for (const def of CURATED) {
513:     const co = coByName.get(def.company);
514:     const users = npcByCompany.get(co?.id) || [];
515:     const owner = users.length ? rng.pick(users) : null;
516:     const seq = game.seq.server++;
517:     const server = makeServer(rng, {
518:       ...def, seq, companyId: co?.id || null, ownerId: owner?.id || null,
519:       files: def.files, vulns: def.vulns, tags: def.tags, status: 'online',
520:       createdWorld: -rng.int(200, 2400), siteKind: def.siteKind, curated: true
521:     });
522:     usedIps.add(server.ip); usedDomains.add(server.domain);
523:     game.servers.push(server);
524:     if (co) co.serverIds.push(server.id);
525:   }
526: 
527:   const roles = ['web frontend','customer portal','internal wiki','mail relay','backup target','CI runner','staging API','metrics collector','database primary','database replica','asset store','status page','VPN concentrator','DNS resolver','jump host','build cache','log archive','payment worker','docs site','edge proxy'];
528:   for (let i = 0; i < 178; i++) {
529:     const co = rng.chance(.86) ? rng.pick(game.companies) : null;
530:     let ip;
531:     const base = rng.chance(.45) ? '198.51.100.' : rng.chance(.55) ? '192.0.2.' : '203.0.113.';
532:     do { ip = base + rng.int(20, 250); } while (usedIps.has(ip));
533:     usedIps.add(ip);
534:     const role = rng.pick(roles);
535:     const slug = slugRole(role) + '-' + i;
536:     let domain = `${slug}.${co ? co.domain : rng.pick(DOMAIN_WORDS) + rng.pick(TLDS)}`;
537:     let domTries = 0;
538:     while (usedDomains.has(domain)) {
539:       domain = `${slug}-${domTries++}.${co ? co.domain : rng.pick(DOMAIN_WORDS) + rng.pick(TLDS)}`;
540:     }
541:     usedDomains.add(domain);
542:     const os = rng.pick(OSES);
543:     const ports = new Set([22]);
544:     if (/web|portal|wiki|status|docs|proxy|api|shop|asset|payment/.test(role)) { ports.add(80); if (rng.chance(.65)) ports.add(443); }
545:     if (/mail/.test(role)) { ports.add(25); ports.add(143); }
546:     if (/database|primary|replica/.test(role)) { ports.add(rng.chance(.5) ? 5432 : 3306); }
547:     if (/cache|metrics/.test(role)) { ports.add(rng.chance(.5) ? 6379 : 9200); }
548:     if (/dns/.test(role)) ports.add(53);
549:     if (rng.chance(.12)) ports.add(8080);
550:     if (rng.chance(.08)) ports.add(21);
551:     if (rng.chance(.06)) ports.add(3389);
552:     const security = clamp(Math.round(rng.float(34, 92) + (co ? (co.security - 65) * .25 : 0)), 18, 97);
553:     const vulnCount = security < 45 ? rng.int(2, 4) : security < 70 ? rng.int(0, 3) : rng.int(0, 1);
554:     const vulns = rng.picks(VULN_TYPES, vulnCount).map(v => makeVuln(rng, v.name, v.service));
555:     const ownerList = co ? (npcByCompany.get(co.id) || []) : [];
556:     const owner = ownerList.length ? rng.pick(ownerList) : rng.pick(game.npcs);
557:     const primary = rng.chance(.5) ? 'deploy' : 'admin';
558:     const siteKind = /web|portal|status|docs|shop|api|wiki/.test(role) && rng.chance(.42) ? 'generic' : null;
559:     const server = makeServer(rng, {
560:       seq: game.seq.server++, ip, host: slug, domain, org: co?.name || 'Independent', companyId: co?.id || null,
561:       ownerId: owner?.id || null, role, os, ports: [...ports], security, vulns,
562:       status: rng.chance(.88) ? 'online' : rng.chance(.5) ? 'degraded' : rng.chance(.5) ? 'maintenance' : 'offline',
563:       tags: rng.picks(TAGS, 2), createdWorld: -rng.int(30, 2600), siteKind, user: primary,
564:       motd: `${slug} — ${role}. All access is logged.\n`,
565:       webroot: `<html><body><h1>${co?.name || 'Independent'}</h1><p>${role}. Status: operational.</p></body></html>`
566:     });
567:     game.servers.push(server);
568:     if (co) co.serverIds.push(server.id);
569:   }
570:   for (const server of game.servers) {
571:     if (!server.siteKind) continue;
572:     const co = game.companies.find(c => c.id === server.companyId);
573:     const owner = game.npcs.find(n => n.id === server.ownerId) || rng.pick(game.npcs);
574:     const kind = server.siteKind;
575:     const title = co ? co.name : server.org === 'NullNet Collective' ? 'NullNet' : server.host;
576:     const desc = co?.desc || `Public services for ${server.org}.`;
577:     const sections = siteSectionsFor(kind, co, server, rng);
578:     const site = makeSite(rng, {
579:       domain: server.domain, title, kind, category: co?.sector || 'community', ownerId: owner.id,
580:       companyId: co?.id || null, serverId: server.id, desc, sections,
581:       links: kind === 'portal' ? ['news.nullnet','market.nullnet','git.nullnet','blackmarket.onion'] : ['portal.nullnet','market.nullnet'],
582:       ownerType: co ? 'company' : 'npc', tech: kind === 'git' ? 'cgit' : 'nginx'
583:     });
584:     game.sites.push(site);
585:     if (co) co.siteId = site.id;
586:   }
587: }
