397: function drawSparkline() {
398:   const canvas = $('#sparkline');
399:   if (!canvas || !app.game) return;
400:   const rect = canvas.getBoundingClientRect();
401:   const w = Math.max(60, Math.round(rect.width || 240));
402:   const h = Math.max(30, canvas.height || 58);
403:   const dpr = Math.min(2, window.devicePixelRatio || 1);
404:   if (canvas.width !== Math.round(w * dpr)) canvas.width = Math.round(w * dpr);
405:   if (canvas.height !== Math.round(h * dpr)) canvas.height = Math.round(h * dpr);
406:   const ctx = canvas.getContext('2d');
407:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
408:   ctx.clearRect(0, 0, w, h);
409:   const data = app.game.market.history.slice(-70);
410:   if (data.length < 2) return;
411:   const min = Math.min(...data), max = Math.max(...data);
412:   const span = Math.max(1, max - min);
413:   const up = data[data.length - 1] >= data[0];
414:   const color = up ? '#79e6a3' : '#e06c75';
415:   ctx.strokeStyle = 'rgba(255,255,255,.045)';
416:   ctx.lineWidth = 1;
417:   for (let y = 0; y <= h; y += 14) { ctx.beginPath(); ctx.moveTo(0, y + .5); ctx.lineTo(w, y + .5); ctx.stroke(); }
418:   const pt = i => [i / (data.length - 1) * w, h - 4 - (data[i] - min) / span * (h - 10)];
419:   ctx.beginPath();
420:   data.forEach((_, i) => { const [x, y] = pt(i); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); });
421:   ctx.strokeStyle = color;
422:   ctx.lineWidth = 1.4;
423:   ctx.stroke();
424:   ctx.lineTo(w, h); ctx.lineTo(0, h); ctx.closePath();
425:   const grad = ctx.createLinearGradient(0, 0, 0, h);
426:   grad.addColorStop(0, up ? 'rgba(121,230,163,.18)' : 'rgba(224,108,117,.18)');
427:   grad.addColorStop(1, 'rgba(0,0,0,0)');
428:   ctx.fillStyle = grad;
429:   ctx.fill();
430: }
