651: function minimizeWindow(win) {
652:   win.minimized = true;
653:   win.el.classList.add('minimized');
654:   if (app.focused === win.kind) {
655:     const next = [...app.windows.values()].filter(w => !w.minimized).sort((a, b) => Number(b.el.style.zIndex) - Number(a.el.style.zIndex))[0];
656:     if (next) focusWindow(next); else app.focused = null;
657:   }
658:   updateDock();
659: }
