456: /* ---------------- the tick ---------------- */
457: export function tickSystems(game, minutes, rng) {
458:   ensureSystems(game);
459:   const events = [];
460:   const day = minutes / DAY;
461:   const c = game.cloud;
462: 
463:   // cloud providers: rare incidents and recoveries
464:   for (const p of c.providers) {
465:     if (p.incidentUntil && game.worldMinutes >= p.incidentUntil) {
466:       p.incidentUntil = 0; p.status = 'operational';
467:       events.push({ type: 'feed', text: `${p.name} reports recovery after a regional incident.`, kind: 'info' });
468:     }
469:     if (!p.incidentUntil && rng.chance(Math.min(.25, .00035 * minutes))) {
470:       p.status = 'degraded'; p.incidentUntil = game.worldMinutes + rng.int(25, 180);
471:       events.push({ type: 'news', headline: `${p.name} reports degraded service in ${rng.pick(p.regions)}`, body: 'Customers describe elevated latency and intermittent API errors. The provider has not published a root cause.', source: 'The Packet' });
472:       events.push({ type: 'feed', text: `${p.name} is degraded in ${rng.pick(p.regions)}.`, kind: 'warn' });
473:     }
474:   }
475: 
476:   // containers on player infrastructure
477:   for (const ctr of c.containers) {
478:     const server = game.servers.find(s => s.id === ctr.serverId);
479:     if (!server) { ctr.status = 'exited'; ctr.logs.push('host removed'); continue; }
480:     if (server.status === 'offline') {
481:       if (ctr.status === 'running') { ctr.status = 'exited'; ctr.restarts++; ctr.logs.push(`${new Date().toISOString()} host went offline`); }
482:       continue;
483:     }
484:     if (ctr.status === 'exited' && ctr.restartPolicy === 'always') {
485:       ctr.status = 'running'; ctr.restarts++;
486:       ctr.logs.push(`${new Date().toISOString()} restarted after host recovery`);
487:     }
488:     if (ctr.status === 'running') {
489:       ctr.uptime += minutes;
490:       const load = ctr.service === 'web' ? rng.float(1, 8) : ctr.service === 'db' ? rng.float(.3, 3) : rng.float(.1, 2);
491:       ctr.requests += Math.round(load * minutes);
492:       if (ctr.service === 'web' && rng.chance(Math.min(.5, .01 * minutes))) {
493:         const site = game.sites.find(s => s.serverId === server.id && s.status === 'live');
494:         if (site) site.visits += rng.int(1, 6);
495:       }
496:       if (rng.chance(Math.min(.35, .004 * minutes))) ctr.logs.push(`${new Date().toISOString()} ${rng.pick(['GET / 200','GET /health 200','POST /api 201','GET /static/app.js 200','upstream timeout, retrying','cache miss'])}`);
497:       if (ctr.logs.length > 60) ctr.logs = ctr.logs.slice(-60);
498:     }
499:   }
500: 
501:   // cluster health
502:   for (const cl of c.clusters) {
503:     const nodes = cl.nodeIds.map(id => game.servers.find(s => s.id === id)).filter(Boolean);
504:     const online = nodes.filter(n => n.status !== 'offline');
505:     cl.status = online.length === 0 ? 'offline' : online.length < nodes.length ? 'degraded' : 'healthy';
506:     for (const w of cl.workloads) {
507:       const capacity = Math.max(1, online.length * 4);
508:       const running = Math.min(w.replicas, capacity);
509:       if (running < w.replicas && rng.chance(Math.min(.5, .006 * minutes))) {
510:         w.restarts = (w.restarts || 0) + 1;
511:         events.push({ type: 'feed', text: `pod ${w.name} rescheduled in ${cl.name}.`, kind: 'warn' });
512:       }
513:       w.running = running;
514:     }
515:   }
516: 
517:   // agents
518:   for (const a of game.agents) {
519:     const role = agentRole(a.roleId);
520:     const model = agentModel(a.modelId);
521:     if (a.ownerType === 'player') {
522:       const server = game.servers.find(s => s.id === a.serverId);
523:       if (a.status === 'active' && (!server || server.status === 'offline')) {
524:         a.status = 'idle'; a.note = 'compute unavailable';
525:         events.push({ type: 'feed', text: `Agent ${a.name} is idle: compute unavailable.`, kind: 'warn' });
526:         continue;
527:       }
528:       if (a.status === 'idle' && server && server.status === 'online') a.status = 'active';
529:       if (a.status !== 'active') continue;
530:       const revenue = agentDailyRevenue(a) * day;
531:       const cost = agentDailyCost(a) * day;
532:       a.pendingRevenue += revenue;
533:       a.pendingCost += cost;
534:       a.spend += cost;
535:       if (a.pendingRevenue >= 1) {
536:         const amount = Math.floor(a.pendingRevenue);
537:         a.pendingRevenue -= amount;
538:         events.push({ type: 'money', amount, memo: `agent ${a.name} output` });
539:       }
540:       if (a.pendingCost >= 1) {
541:         const amount = Math.floor(a.pendingCost);
542:         a.pendingCost -= amount;
543:         events.push({ type: 'money', amount: -amount, memo: `agent ${a.name} model usage` });
544:       }
545:       if (a.siteId && rng.chance(Math.min(.6, .02 * minutes))) {
546:         const site = game.sites.find(s => s.id === a.siteId);
547:         if (site) site.visits += rng.int(1, 4);
548:       }
549:       if (rng.chance(Math.min(.9, .012 * minutes))) {
550:         a.tasksDone++;
551:         const task = rng.pick(AGENT_TASKS);
552:         a.memory.push({ world: game.worldMinutes, text: task });
553:         if (a.memory.length > 24) a.memory.shift();
554:         if (rng.chance(.16)) events.push({ type: 'feed', text: `Agent ${a.name} ${task}.`, kind: 'info' });
555:       }
556:       if (rng.chance(Math.min(.5, role.risk * day * 1.8))) {
557:         a.status = 'paused';
558:         const note = rng.pick([
559:           'Produced a confident answer with no supporting source. Paused pending review.',
560:           'Attempted an action outside its permission scope. Request denied and logged.',
561:           'Escalated an ambiguous customer request instead of guessing. Correct behavior.',
562:           'Repeated a stale runbook step. Paused until the runbook is updated.'
563:         ]);
564:         a.memory.push({ world: game.worldMinutes, text: note });
565:         events.push({ type: 'feed', text: `Agent ${a.name} paused: ${note}`, kind: 'warn' });
566:         events.push({ type: 'mail', from: 'agent-ops', subject: `Agent ${a.name} needs review`, body: `${note}\n\nReview with: agent inspect ${a.name}\nResume with: agent start ${a.name}` });
567:       }
568:     } else {
569:       if (rng.chance(Math.min(.8, .006 * minutes))) {
570:         a.tasksDone++;
571:         a.memory.push({ world: game.worldMinutes, text: rng.pick(AGENT_TASKS) });
572:         if (a.memory.length > 16) a.memory.shift();
573:         if (rng.chance(.05)) events.push({ type: 'feed', text: `${a.ownerName}'s agent ${a.name} ${rng.pick(AGENT_TASKS)}.`, kind: 'info' });
574:       }
575:     }
576:   }
577: 
578:   // organizations, products and market drift
579:   for (const co of game.companies) {
580:     const products = (co.products || []).map(id => game.products.find(p => p.id === id)).filter(Boolean);
581:     let mrr = 0;
582:     for (const p of products) {
583:       if (p.status !== 'live') continue;
584:       mrr += p.price * p.subscribers;
585:       if (day > 0) {
586:         const churn = p.churn || .002;
587:         const growth = p.growth || 0;
588:         p.subscribers = Math.max(0, p.subscribers * (1 + (growth - churn) * day * 30));
589:         p.rating = clamp(p.rating + rng.float(-.04, .04) * day, 1, 5);
590:       }
591:     }
592:     co.revenue = Math.round(mrr);
593:     if (co.status === 'failed') continue;
594:     const profit = (mrr - (co.burn || 0)) * day / 30;
595:     co.funds += profit;
596:     if (co.ownerType === 'player') {
597:       // retained earnings first, then a dividend to the operator
598:       for (const p of products) {
599:         if (p.status !== 'live') continue;
600:         const reach = clamp((game.player.reputation || 0) / 100 + Math.min(.5, (game.player.domains?.length || 0) * .03), 0, 1);
601:         const acquisition = (1.2 + reach * 2.8) * day;
602:         const churn = p.subscribers * (p.churn || .002) * day;
603:         p.subscribers = Math.max(0, p.subscribers + acquisition - churn);
604:       }
605:       if (profit > 0) {
606:         const dividend = Math.floor(profit * .5);
607:         if (dividend >= 1) {
608:           co.funds -= dividend;
609:           events.push({ type: 'money', amount: dividend, memo: `${co.name} dividend` });
610:         }
611:       }
