190: function objectiveFor(type, server, extra = {}) {
191:   const host = server ? server.host : extra.targetLabel || 'target';
192:   const base = { type, target: server?.id || null, label: '', hint: '' };
193:   if (type === 'scan') return { ...base, label: `Enumerate exposed services on ${host}`, hint: `nmap -sV ${host}` };
194:   if (type === 'audit') return { ...base, label: `Audit ${host} and document a real finding`, hint: `nmap -sV ${host} && audit ${host}` };
195:   if (type === 'patch') return { ...base, label: `Close the known exposure on ${host}`, hint: `patch ${host}` };
196:   if (type === 'exploit') return { ...base, label: `Obtain access to ${host} and retrieve the archive`, hint: `nmap -sV ${host} && vulnscan ${host} && exploit ${host}` };
197:   if (type === 'deploy') return { ...base, label: 'Publish a live site on infrastructure you own', hint: 'buy vps-std, then deploy <dir> <domain>' };
198:   if (type === 'code') return { ...base, label: `Deliver ${extra.path || 'the requested artifact'}`, hint: `create the file at ${extra.path || '~/projects'}`, path: extra.path, minLines: extra.minLines || 4 };
199:   return { ...base, label: `Complete the work for ${host}`, hint: '' };
200: }
