258:       funds: def.funds, founded: 2026 - rng.int(2, 24), employees: def.size,
259:       serverIds: [], siteId: null, ceoId: null, status: 'operating',
260:       projects: rng.picks(['migration','audit','launch','cost reduction','hiring','incident review','platform rebuild','regional expansion'], 2),
261:       hq: rng.pick(REGIONS)
262:     });
263:   }
