325: export function clusterPods(game, cluster) {
326:   const nodes = cluster.nodeIds.map(id => game.servers.find(s => s.id === id)).filter(Boolean);
327:   const online = nodes.filter(n => n.status !== 'offline');
328:   const pods = [];
329:   for (const w of cluster.workloads) {
330:     const capacity = Math.max(1, online.length * 4);
331:     const running = Math.min(w.replicas, capacity);
332:     for (let i = 0; i < w.replicas; i++) {
333:       const node = online[i % Math.max(1, online.length)];
334:       pods.push({
335:         name: `${w.name}-${String(i + 1).padStart(2, '0')}`, workload: w.name, image: w.image,
336:         status: i < running ? 'Running' : 'Pending', node: node?.host || 'none', restarts: w.restarts || 0
337:       });
338:     }
339:   }
340:   return pods;
341: }
