456: /* ---------------- the tick ---------------- */
457: export function tickSystems(game, minutes, rng) {
458:   ensureSystems(game);
459:   const events = [];
460:   const day = minutes / DAY;
461:   const c = game.cloud;
462: 
463:   // cloud providers: rare incidents and recoveries
464:   for (const p of c.providers) {
465:     if (p.incidentUntil && game.worldMinutes >= p.incidentUntil) {
466:       p.incidentUntil = 0; p.status = 'operational';
467:       events.push({ type: 'feed', text: `${p.name} reports recovery after a regional incident.`, kind: 'info' });
468:     }
469:     if (!p.incidentUntil && rng.chance(Math.min(.25, .00035 * minutes))) {
470:       p.status = 'degraded'; p.incidentUntil = game.worldMinutes + rng.int(25, 180);
471:       events.push({ type: 'news', headline: `${p.name} reports degraded service in ${rng.pick(p.regions)}`, body: 'Customers describe elevated latency and intermittent API errors. The provider has not published a root cause.', source: 'The Packet' });
472:       events.push({ type: 'feed', text: `${p.name} is degraded in ${rng.pick(p.regions)}.`, kind: 'warn' });
473:     }
474:   }
475: 
476:   // containers on player infrastructure
477:   for (const ctr of c.containers) {
478:     const server = game.servers.find(s => s.id === ctr.serverId);
479:     if (!server) { ctr.status = 'exited'; ctr.logs.push('host removed'); continue; }
480:     if (server.status === 'offline') {
481:       if (ctr.status === 'running') { ctr.status = 'exited'; ctr.restarts++; ctr.logs.push(`${new Date().toISOString()} host went offline`); }
482:       continue;
483:     }
484:     if (ctr.status === 'exited' && ctr.restartPolicy === 'always') {
485:       ctr.status = 'running'; ctr.restarts++;
486:       ctr.logs.push(`${new Date().toISOString()} restarted after host recovery`);
487:     }
488:     if (ctr.status === 'running') {
