1225: export function objectiveSatisfied(game, contract) {
1226:   const o = contract.objective;
1227:   if (!o) return false;
1228:   if (o.type === 'scan') return !!game.flags.scanned[o.target];
1229:   if (o.type === 'audit') return !!game.flags.audited[o.target];
1230:   if (o.type === 'patch') return !!game.flags.patched[o.target];
1231:   if (o.type === 'exploit') return !!game.flags.exploited[o.target];
1232:   if (o.type === 'deploy') return game.stats.deploys > 0 || playerSites(game).length > 0;
1233:   if (o.type === 'code') {
1234:     const path = o.path?.startsWith('/') ? o.path : resolvePath(HOME, o.path || '');
1235:     const node = getNode(game.fs, path);
1236:     if (!node || node.type !== 'file') return false;
1237:     return node.content.trim().split('\n').length >= (o.minLines || 4);
1238:   }
1239:   return false;
1240: }
