1417: export function exploitServer(game, server, vulnId) {
1418:   if (!server) return { ok: false, error: 'No such host.' };
1419:   if (server.status === 'offline') return { ok: false, error: 'Host is offline.' };
1420:   const candidates = server.vulns.filter(v => !v.patched && v.discovered);
1421:   if (!candidates.length) return { ok: false, error: 'No discovered exploit vector. Run: vulnscan ' + server.host };
1422:   const vuln = vulnId ? candidates.find(v => v.id.toLowerCase() === String(vulnId).toLowerCase()) : candidates.sort((a, b) => (b.severity === 'critical') - (a.severity === 'critical'))[0];
1423:   if (!vuln) return { ok: false, error: 'That vulnerability is not known on this host.' };
1424:   if (server.host === 'cybernet') {
1425:     addHeat(game, 45, 'interaction with a monitored regulator host');
1426:     const ev = investigate(game, 'unauthorized interaction with CyberNet infrastructure');
1427:     return { ok: false, error: 'The connection is terminated immediately. A regulator trace has been opened.', legal: ev };
1428:   }
1429:   const rng = makeRng((game.seed ^ game.worldMinutes ^ server.id.length ^ 0xabc) >>> 0);
1430:   const skill = getPlayerSkill(game);
1431:   const sevBonus = vuln.severity === 'critical' ? .18 : vuln.severity === 'high' ? .1 : 0;
1432:   let chance = clamp(.48 + skill * .045 + sevBonus - server.security * .0065, .08, .94);
1433:   if (server.compromised) chance = .98;
1434:   const success = rng.chance(chance);
1435:   if (!success) {
1436:     addHeat(game, 9 + (100 - server.security) * .05, `failed intrusion attempt on ${server.host}`);
1437:     server.history.unshift({ time: Date.now(), text: 'Failed intrusion attempt detected.' });
1438:     return { ok: false, error: 'Exploit failed. The service reset the connection. You may have left a trace.' };
1439:   }
1440:   server.compromised = true;
1441:   game.flags.exploited[server.id] = { time: Date.now(), vuln: vuln.id };
1442:   game.flags.hacked[server.id] = true;
1443:   game.stats.exploits++;
1444:   addHeat(game, 8 + (vuln.severity === 'critical' ? 8 : 4) + (100 - server.security) * .08, `intrusion on ${server.host}`);
1445:   const loot = [];
1446:   const files = allFiles(server.fs, '/');
1447:   for (const f of files) {
1448:     if (/(backup|manifest|\.env|README|notes|conf)$/i.test(f.path) && loot.length < 3) {
1449:       const dest = `/home/operator/downloads/${server.host}-${f.path.split('/').pop()}`;
1450:       writeFile(game.fs, dest, f.node.content, { owner: 'operator' });
1451:       loot.push(dest);
1452:     }
1453:   }
1454:   server.notes.unshift(`Compromised at cycle ${worldClock(game).cycle}; access retained.`);
1455:   addFeed(game, `Shell obtained on ${server.host} (${server.ip}) via ${vuln.id}.`, 'bad');
1456:   checkAchievements(game);
1457:   return { ok: true, server, vuln, loot, user: 'root' };
1458: }
