3: export function hash32(str) {
4:   let h = 2166136261 >>> 0;
5:   for (let i = 0; i < str.length; i++) {
6:     h ^= str.charCodeAt(i);
7:     h = Math.imul(h, 16777619);
8:   }
9:   return h >>> 0;
10: }
