22: export function makeRng(seed) {
23:   const fn = mulberry32(typeof seed === 'string' ? hash32(seed) : seed >>> 0);
24:   return {
25:     next: fn,
26:     int(a, b) { return a + Math.floor(fn() * (b - a + 1)); },
27:     float(a, b) { return a + fn() * (b - a); },
28:     chance(p) { return fn() < p; },
29:     pick(arr) { return arr[Math.floor(fn() * arr.length)]; },
30:     picks(arr, n) {
31:       const copy = arr.slice();
32:       const out = [];
33:       while (copy.length && out.length < n) out.push(copy.splice(Math.floor(fn() * copy.length), 1)[0]);
34:       return out;
35:     },
36:     shuffle(arr) {
37:       const a = arr.slice();
38:       for (let i = a.length - 1; i > 0; i--) {
39:         const j = Math.floor(fn() * (i + 1));
40:         [a[i], a[j]] = [a[j], a[i]];
41:       }
42:       return a;
43:     },
44:     hex(n = 8) {
45:       let s = '';
46:       for (let i = 0; i < n; i++) s += Math.floor(fn() * 16).toString(16);
47:       return s;
48:     },
49:     weighted(pairs) {
50:       const total = pairs.reduce((s, p) => s + p[1], 0);
51:       let r = fn() * total;
52:       for (const [v, w] of pairs) { r -= w; if (r <= 0) return v; }
53:       return pairs[pairs.length - 1][0];
