265: function buildNpcs(game, rng) {
266:   const used = new Set();
267:   const byCompany = new Map(game.companies.map(c => [c.name, c]));
268:   for (const k of KEY_NPCS) {
269:     used.add(k.handle);
270:     const co = byCompany.get(k.company);
271:     const npc = {
272:       ...k, id: `npc-${String(game.seq.npc++).padStart(4, '0')}`,
273:       companyId: co?.id || null, email: `${k.handle}@${co?.domain || 'nullnet'}`,
274:       online: rng.chance(.6), activity: rng.pick(ACTIVITIES), mood: rng.pick(['calm','focused','busy','wary']),
275:       faction: co?.sector === 'government' ? 'gov' : k.company === 'independent' ? (k.rep < 45 ? 'underground' : 'civilian') : 'corp',
276:       relations: {}, key: true, sent: 0, received: 0
277:     };
278:     game.npcs.push(npc);
279:     if (co && !co.ceoId) co.ceoId = npc.id;
280:     if (co) co.rep = clamp(co.rep + rng.int(-2, 3), 1, 99);
281:   }
282:   for (let i = 0; i < 104; i++) {
283:     const id = makeIdentity(rng, used);
284:     const co = rng.chance(.78) ? rng.pick(game.companies) : null;
285:     const npc = {
286:       ...id, id: `npc-${String(game.seq.npc++).padStart(4, '0')}`,
287:       companyId: co?.id || null, company: co?.name || 'independent',
288:       email: `${id.handle}@${co?.domain || 'nullnet'}`,
289:       online: rng.chance(.45), activity: rng.pick(ACTIVITIES),
290:       faction: co?.sector === 'government' ? 'gov' : (!co && id.rep < 38) ? 'underground' : 'civilian',
291:       key: false, sent: 0, received: 0
292:     };
293:     game.npcs.push(npc);
294:   }
295:   for (const npc of game.npcs.filter(n => n.key)) {
296:     for (const other of rng.picks(game.npcs.filter(n => n.key && n.handle !== npc.handle), rng.int(1, 3))) {
297:       npc.relations[other.handle] = rng.int(-40, 80);
298:     }
299:   }
300:   for (const npc of game.npcs) {
301:     game.player.relations[npc.handle] = npc.key && ['hex','pixel','fable','relay'].includes(npc.handle) ? rng.int(0, 8) : 0;
302:   }
303: }
