1495: export function tickWorld(game, minutes = 1, opts = {}) {
1496:   ensureSystems(game);
1497:   const rng = makeRng((game.seed ^ Math.floor(game.worldMinutes * 2654435761) ^ (game.tickCount * 97)) >>> 0);
1498:   minutes = Math.max(1, Math.round(minutes));
1499:   game.worldMinutes += minutes;
1500:   game.tickCount++;
1501:   const events = [];
1502:   const before = { money: game.player.money, mail: game.mail.length, contracts: game.contracts.length, sites: game.sites.length, heat: game.player.heat };
1503: 
1504:   // market random walk
1505:   const drift = (rng.next() - .5) * .006 + .00015;
1506:   game.market.index = clamp(game.market.index * (1 + drift), 720, 1480);
1507:   game.market.history.push(Math.round(game.market.index * 10) / 10);
1508:   if (game.market.history.length > 80) game.market.history.shift();
1509:   game.market.volume = Math.max(0, Math.round(game.market.volume * .94 + rng.int(120, 2400)));
1510:   game.market.sentiment = game.market.index > 1120 ? 'bullish' : game.market.index < 900 ? 'bearish' : 'neutral';
1511: 
1512:   // people keep moving
1513:   const npcUpdates = Math.min(6, 1 + Math.floor(minutes / 10));
1514:   for (let i = 0; i < npcUpdates; i++) {
1515:     const npc = rng.pick(game.npcs);
1516:     npc.online = rng.chance(.46);
1517:     npc.activity = rng.pick(ACTIVITIES);
1518:     npc.mood = rng.pick(['calm','busy','curious','tired','focused','wary']);
1519:     if (rng.chance(.006 * Math.min(minutes, 30))) {
1520:       npc.rep = clamp(npc.rep + rng.int(-1, 1), 0, 100);
1521:       if (rng.chance(.35)) addFeed(game, `@${npc.handle} is ${npc.activity}.`, 'info');
1522:     }
1523:   }
1524: 
1525:   // infrastructure events
1526:   const serverEvents = Math.max(1, Math.min(4, Math.ceil(minutes / 30)));
1527:   for (let i = 0; i < serverEvents; i++) {
1528:     const server = rng.pick(game.servers);
1529:     if (!server) continue;
1530:     if (server.owned) {
1531:       if (rng.chance(.015)) {
1532:         server.notes.unshift(rng.pick(MAINT_NOTES));
1533:         if (server.notes.length > 8) server.notes.length = 8;
1534:       }
1535:       continue;
1536:     }
1537:     if (server.status === 'offline' && rng.chance(.24)) {
1538:       server.status = 'online';
1539:       server.notes.unshift('Host recovered and rejoined the network.');
1540:       addFeed(game, `${server.host} is back online.`, 'info');
1541:       events.push({ type: 'recovery', text: `${server.host} recovered` });
1542:     } else if (server.status === 'maintenance' && rng.chance(.3)) {
1543:       server.status = 'online';
1544:       server.notes.unshift(rng.pick(MAINT_NOTES));
1545:     } else if (server.status === 'online' && rng.chance(.035)) {
1546:       server.status = rng.chance(.55) ? 'degraded' : rng.chance(.5) ? 'maintenance' : 'offline';
1547:       server.notes.unshift(server.status === 'degraded' ? 'Latency elevated; incident opened.' : server.status === 'maintenance' ? 'Scheduled maintenance started.' : 'Host unreachable.');
1548:       if (server.notes.length > 8) server.notes.length = 8;
1549:       if (server.status === 'offline') addFeed(game, `${server.host} went offline.`, 'bad');
1550:       events.push({ type: 'status', text: `${server.host} ${server.status}` });
1551:     }
1552:     if (server.status === 'online') {
1553:       server.traffic = Math.max(0, Math.round(server.traffic * (1 + rng.float(-.03, .04))));
1554:       if (server.vulns.some(v => !v.patched) && rng.chance(.012)) {
1555:         server.compromised = true;
1556:         server.security = clamp(server.security - rng.int(2, 8), 0, 99);
1557:         const news = addNews(game, rng, { silent: true });
1558:         events.push({ type: 'compromise', text: `${server.host} compromised` });
1559:         if (rng.chance(.5)) addFeed(game, `${server.host} shows signs of compromise.`, 'bad');
1560:       }
1561:       if (server.security < 52 && rng.chance(.018)) {
1562:         const v = makeVuln(rng, rng.pick(VULN_TYPES).name);
1563:         if (!server.vulns.some(x => x.name === v.name && !x.patched)) {
1564:           server.vulns.push(v);
1565:           server.notes.unshift(`New exposure discovered: ${v.name}.`);
1566:         }
1567:       }
1568:       if (server.vulns.some(v => !v.patched) && rng.chance(.02)) {
1569:         const v = server.vulns.find(x => !x.patched);
1570:         v.patched = true;
1571:         server.security = clamp(server.security + 2, 0, 99);
1572:       }
