1574:     }
1575:   }
1576: 
1577:   // news + forum life
1578:   if (rng.chance(Math.min(.9, .028 * minutes))) {
1579:     const n = addNews(game, rng, { silent: false });
1580:     events.push({ type: 'news', text: n.headline });
1581:   }
1582:   if (rng.chance(Math.min(.75, .022 * minutes))) {
1583:     const forum = rng.pick(game.forums.filter(f => f.status === 'live'));
1584:     if (forum && forum.threads.length) {
