1628: 
1629:   // Passive site traffic and revenue accrue at every crossed ten-minute boundary,
1630:   // including when a large offline-simulation chunk skips several boundaries.
1631:   const previousWorldMinute = game.worldMinutes - minutes;
1632:   const intervals = Math.floor(game.worldMinutes / 10) - Math.floor(previousWorldMinute / 10);
1633:   for (let interval = 0; interval < intervals; interval++) {
1634:     for (const site of playerSites(game)) {
1635:       const gain = Math.max(1, Math.round(site.visits * rng.float(.004, .012)) + rng.int(1, 8));
1636:       site.visits += gain;
