1012: export function getServer(game, query) {
1013:   if (!query) return null;
1014:   let q = String(query).trim().toLowerCase();
1015:   q = q.replace(/^ssh:\/\//, '').replace(/^https?:\/\//, '').split('/')[0];
1016:   if (q.includes('@')) q = q.split('@').pop();
1017:   q = q.replace(/:\d+$/, '');
1018:   const site = getSite(game, q);
1019:   if (site?.serverId) {
1020:     const bySite = game.servers.find(s => s.id === site.serverId);
1021:     if (bySite) return bySite;
1022:   }
1023:   return game.servers.find(s => s.ip === q || s.host.toLowerCase() === q || s.domain.toLowerCase() === q) || null;
1024: }
1025: export function getSite(game, query) {
1026:   if (!query) return null;
1027:   const q = String(query).trim().toLowerCase().replace(/^https?:\/\//, '').split('/')[0].replace(/:\d+$/, '');
1028:   return game.sites.find(s => s.domain.toLowerCase() === q) || null;
1029: }
1030: export function getNpc(game, query) {
1031:   if (!query) return null;
1032:   const q = String(query).trim().toLowerCase().replace(/^@/, '');
1033:   return game.npcs.find(n => n.handle.toLowerCase() === q || n.id === q || n.name.toLowerCase() === q) || null;
1034: }
1035: export function getCompany(game, query) {
1036:   if (!query) return null;
1037:   const q = String(query).trim().toLowerCase();
1038:   return game.companies.find(c => c.name.toLowerCase() === q || c.domain.toLowerCase() === q || c.id === q) || null;
1039: }
1040: export function getContract(game, id) {
1041:   const q = String(id || '').toUpperCase();
1042:   return game.contracts.find(c => c.id.toUpperCase() === q || c.id === id) || null;
1043: }
1044: export function playerSites(game) { return game.sites.filter(s => s.ownerType === 'player' || s.ownerId === 'player'); }
1045: export function ownedServers(game) { return game.servers.filter(s => s.owned); }
1046: export function onlineNpcs(game) { return game.npcs.filter(n => n.online); }
1047: export function onlineCount(game) { return onlineNpcs(game).length + 36 + (game.tickCount % 17); }
1048: export function marketIndex(game) { return Math.round(game.market.index * 10) / 10; }
1049: export function netWorth(game) {
1050:   const owned = ownedServers(game);
1051:   const serverValue = owned.reduce((s, x) => s + (x.plan === 'dedicated' ? 1800 : x.plan === 'standard' ? 700 : 260), 0);
1052:   const siteValue = playerSites(game).reduce((s, x) => s + Math.min(4000, Math.round(x.visits * .25)), 0);
1053:   const inv = Object.values(game.player.inventory || {}).reduce((s, n) => s + Number(n || 0), 0) * 40;
1054:   return game.player.money + serverValue + siteValue + game.player.domains.length * 18 + inv;
1055: }
1056: export function getPlayerSkill(game) {
1057:   const s = game.stats;
