+  market.rentIndex = clamp(market.rentIndex + (rng.next() - .5) * .6 + (civ.metrics.growth - 2) * .03, 45, 240);
+  market.vacancy = clamp(market.vacancy + (rng.next() - .52) * .3, 1, 32);
