789:       incidents: rng.chance(.12) ? rng.int(1, 4) : 0, credentials: rng.chance(.4) ? ['hardware-key'] : []
790:     },
791:     financial: {
792:       score: clamp(30 + Math.log10(Math.max(100, npc.funds || 1000)) * 9 + rng.int(-8, 8), 5, 99),
793:       credit: rng.int(420, 820), assets: Math.round((npc.funds || 0) * rng.float(.1, .8))
794:     },
795:     academic: {
796:       score: clamp(20 + (npc.skill || 50) * .5 + rng.int(-10, 20), 3, 99),
797:       publications: rng.chance(.35) ? rng.int(1, 24) : 0, citations: rng.int(0, 800),
798:       field: rng.pick(['cs', 'ai', 'security', 'networks', 'economics', 'design'])
799:     },
800:     credentials: [], published: [], updatedWorld: civ.worldMinutes
801:   };
802: }
