809: function assignCompanyJurisdictions(civ, game, rng = null) {
810:   const byRegion = {
811:     'us-east': ['novaria'], 'us-west': ['novaria'], 'eu-west': ['albion', 'rhine'],
812:     'eu-north': ['nordhavn'], 'ap-south': ['sakura', 'sundara', 'coral'],
813:     'sa-east': ['pampas'], 'af-south': ['atlas']
814:   };
815:   for (const co of game.companies || []) {
816:     if (co.hqCountryId && civ.countries.some(c => c.id === co.hqCountryId)) continue;
817:     const candidates = byRegion[co.hq] || [];
818:     const countryId = candidates.length ? (rng ? rng.pick(candidates) : candidates[0]) : 'novaria';
819:     co.hqCountryId = countryId;
820:     co.jurisdiction = civ.countries.find(c => c.id === countryId)?.name || 'Novaria';
821:   }
822: }
