824: /* ============================================================
825:    BUILD ROOT
826:    ============================================================ */
827: export function buildCivilization(game, rng = null) {
828:   rng = rng || makeRng((game.seed ^ 0x1c1b1a19) >>> 0);
829:   const civ = {
830:     version: CIV_VERSION, builtWorld: game.worldMinutes, seq: {},
831:     countries: [], cities: [], institutions: [], laws: [], courts: [], regulators: [],
832:     disputes: [], compliance: [], policies: [],
833:     relations: { treaties: [], sanctions: [], negotiations: [], blocs: [] },
834:     education: { institutions: [], courses: [], certifications: [], enrollments: [], player: { knowledge: {}, credentials: [], studyHours: 0, enrolled: null } },
835:     research: { fields: RESEARCH_FIELDS.map(f => ({ id: f.id, name: f.name, code: f.code, level: 1, progress: rng.int(0, 40), funding: rng.int(100000, 4000000), discoveries: [] })), labs: [], projects: [], discoveries: [] },
836:     media: { outlets: [], content: [], publicOpinion: {}, trends: [], playerPublished: [] },
837:     infrastructure: null, property: { listings: [], owned: [], market: { index: 100, rentIndex: 100, vacancy: 7, lastUpdateWorld: game.worldMinutes } },
838:     supply: null, tech: { technologies: [], standards: [], lastReleaseWorld: game.worldMinutes },
839:     culture: { organizations: [], games: [], music: [], communities: [], esports: [], events: [] },
840:     identities: [], player: null,
841:     events: [], timeline: [], cadence: { continuous: 0, politics: 0, economy: 0, supply: 0, media: 0, research: 0, events: 0, history: 0, property: 0, education: 0, infrastructure: 0 },
842:     metrics: {}, multiplayer: null, _companies: (game.companies || []).slice(), _npcIds: []
843:   };
844:   civ.worldMinutes = game.worldMinutes;
845: 
846:   civ.countries = COUNTRY_DEFS.map(def => makeCountry(def, rng));
847:   civ.cities = CITY_DEFS.map(def => makeCity(def, civ.countries.find(c => c.id === def[1]), rng));
848:   assignCompanyJurisdictions(civ, game, rng);
849: 
850:   // Institutions and legal architecture.
851:   for (const country of civ.countries) {
852:     country.institutions = [
853:       makeInstitution(civ, country, 'legislature', `${country.name} National Assembly`, rng),
854:       makeInstitution(civ, country, 'court', `${country.name} High Court`, rng),
855:       makeInstitution(civ, country, 'regulator', `${country.name} ${country.cyberPolicy === 'strict' ? 'Cyber Oversight Board' : 'Digital Services Office'}`, rng)
856:     ];
857:     civ.institutions.push(...country.institutions);
858:     civ.courts.push({ ...country.institutions[1], jurisdiction: country.id, type: 'high', cases: rng.int(20, 320) });
859:     civ.regulators.push({ ...country.institutions[2], domain: 'digital', investigations: rng.int(2, 80) });
860:     for (const domain of LAW_DOMAINS) {
861:       civ.laws.push(makeLaw(civ, country, domain, rng));
862:     }
863:     // A live amendment in selected jurisdictions.
864:     if (rng.chance(.55)) {
865:       const domain = rng.pick(LAW_DOMAINS);
866:       const proposal = makeLaw(civ, country, domain, rng, 'proposed');
867:       proposal.effectiveWorld = game.worldMinutes + rng.int(20, 160) * DAY;
868:       civ.laws.push(proposal);
869:       civ.policies.push({ id: nextId(civ, 'policy'), countryId: country.id, domain: domain.id, name: `Amendment to the ${domain.name.toLowerCase()} framework`, status: 'proposed', support: rng.int(28, 72), introducedWorld: game.worldMinutes, effectiveWorld: proposal.effectiveWorld, effect: 'regulatory tightening' });
870:     }
871:     country.nextElection = game.worldMinutes + rng.int(60, 900) * DAY;
872:     country.internetFreedom = clamp(100 - country.internet.censorship * 1.3 + country.regulation.privacy * .25, 0, 100);
873:   }
874: 
875:   // Relations before the player arrives.
876:   for (const a of civ.countries) {
877:     for (const b of civ.countries) {
878:       if (a.id === b.id) continue;
879:       const shared = a.region === b.region ? 12 : 0;
880:       a.relations[b.id] = {
881:         trade: clamp(rng.int(24, 78) + shared, 0, 100),
882:         tension: clamp(rng.int(4, 38) - shared / 2, 0, 100),
883:         trust: clamp(rng.int(28, 78) + shared, 0, 100),
884:         stance: rng.pick(['cooperative', 'neutral', 'cautious', 'competitive']),
885:         treaty: rng.chance(.22), sanctioned: false
886:       };
887:     }
888:   }
889:   for (let i = 0; i < 6; i++) {
890:     const a = rng.pick(civ.countries), b = rng.pick(civ.countries.filter(c => c.id !== a.id));
891:     civ.relations.treaties.push({
892:       id: nextId(civ, 'treaty'), a: a.id, b: b.id, name: rng.pick(['Cross-border Data Accord', 'Mutual Incident Notification Pact', 'Critical Infrastructure Convention', 'Technology Trade Framework']),
893:       signedWorld: game.worldMinutes - rng.int(1, 16) * YEAR, status: 'active', compliance: rng.int(42, 94)
894:     });
895:     a.relations[b.id].treaty = true; b.relations[a.id].treaty = true;
896:   }
897: 
898:   // Education.
899:   for (const country of civ.countries) {
900:     for (const name of country.universities) civ.education.institutions.push(makeInstitutionFromCountry(civ, country, name, rng));
901:   }
902:   const onlineEd = [
903:     ['Open Bench Academy', 'global', 'online', 78], ['Night Shift Labs', 'global', 'online', 71],
904:     ['Meridian Extension', 'novaria', 'online', 84], ['Sundar Skills Network', 'sundara', 'online', 62],
905:     ['Harborview Field School', 'coral', 'training', 74]
906:   ];
907:   for (const [name, scope, type, quality] of onlineEd) {
908:     const country = scope === 'global' ? rng.pick(civ.countries) : civ.countries.find(c => c.id === scope);
909:     civ.education.institutions.push({
910:       id: nextId(civ, 'edu'), name, type, countryId: country?.id || null, cityId: type === 'online' ? null : rng.pick(civ.cities).id,
911:       quality, capacity: rng.int(5000, 120000), tuition: type === 'online' ? 0 : Math.round(900 * country.costIndex),
912:       researchOutput: rng.int(20, 82), endowment: type === 'online' ? 0 : Math.round(country.economy.gdp * .00005),
913:       fields: rng.picks(EDU_FIELDS, rng.int(5, 10)).map(f => f.id), status: 'open'
914:     });
915:   }
916:   for (const field of EDU_FIELDS) {
917:     const eligible = civ.education.institutions.filter(i => i.fields.includes(field.id));
918:     for (const inst of rng.picks(eligible.length ? eligible : civ.education.institutions, Math.min(4, eligible.length || 3))) {
919:       civ.education.courses.push(makeCourse(civ, field, inst, civ.countries.find(c => c.id === inst.countryId), rng));
920:     }
921:     civ.education.certifications.push({ id: nextId(civ, 'cert'), field: field.id, name: field.cert, provider: rng.pick(eligible.length ? eligible : civ.education.institutions).name, cost: Math.round(field.cost * 1.8), status: 'available' });
922:   }
923: 
924:   // Research labs and history.
925:   const labOwners = civ._companies.filter(c => ['research', 'software', 'data', 'security', 'infrastructure', 'cloud', 'manufacturing', 'biotech'].includes(c.sector));
926:   for (const country of civ.countries) {
927:     for (const inst of civ.education.institutions.filter(i => i.countryId === country.id).slice(0, 2)) {
928:       civ.research.labs.push(makeLab(civ, `${inst.name} Research Group`, 'university', country.id, rng, inst.id));
929:     }
930:   }
931:   for (const co of labOwners.slice(0, 10)) {
932:     const country = countryForCompany(civ, co);
933:     civ.research.labs.push(makeLab(civ, `${co.name} Research`, 'corporate', country?.id || null, rng, co.id));
934:   }
935:   civ.research.labs.push(makeLab(civ, 'Independent Field Lab', 'independent', rng.pick(civ.countries).id, rng));
936:   for (const field of RESEARCH_FIELDS) {
937:     const discovered = field.discoveries.filter(d => d.tier === 1 && rng.chance(.55));
938:     for (const template of discovered) {
939:       const lab = rng.pick(civ.research.labs);
940:       const discovery = makeDiscovery(civ, field, template, rng, {
941:         world: game.worldMinutes - rng.int(2, 14) * YEAR,
942:         labId: lab.id, countryId: lab.countryId, replicated: rng.chance(.7)
943:       });
944:       civ.research.discoveries.push(discovery);
945:       civ.research.fields.find(f => f.id === field.id).discoveries.push(discovery.id);
946:       civ.research.fields.find(f => f.id === field.id).level = Math.max(1, template.tier + 1);
947:     }
948:   }
949:   for (let i = 0; i < 14; i++) {
950:     const field = rng.pick(RESEARCH_FIELDS);
951:     const lab = rng.pick(civ.research.labs);
952:     const tier = Math.min(3, (civ.research.fields.find(f => f.id === field.id).level || 1));
953:     civ.research.projects.push(makeProject(civ, field, lab, civ.countries.find(c => c.id === lab.countryId), rng, { tier }));
954:   }
955: 
956:   // Media.
957:   for (const seed of MEDIA_SEEDS) civ.media.outlets.push(makeOutlet(civ, seed, rng));
958:   for (const country of civ.countries) {
959:     civ.media.publicOpinion[country.id] = {
960:       government: clamp(country.approval + rng.int(-10, 10), 0, 100),
961:       technology: rng.int(38, 78), privacy: clamp(country.regulation.privacy + rng.int(-12, 12), 0, 100),
962:       mediaTrust: rng.int(28, 72), optimism: rng.int(30, 74), polarization: rng.int(20, 76)
963:     };
964:   }
965:   for (let i = 0; i < 24; i++) {
966:     const outlet = rng.pick(civ.media.outlets);
967:     civ.media.content.push(makeContent(civ, outlet, rng, { world: game.worldMinutes - rng.int(1, 48) * 60 }));
968:   }
969:   civ.media.trends = rng.picks(['infrastructure costs', 'AI regulation', 'privacy', 'semiconductor supply', 'remote work', 'platform accountability', 'open source', 'gaming', 'digital identity', 'energy prices'], 6)
970:     .map(topic => ({ topic, volume: rng.int(20, 100), sentiment: rng.int(-50, 50), updatedWorld: game.worldMinutes }));
971: 
972:   // Physical infrastructure.
973:   civ.infrastructure = makeInfrastructure(civ, rng);
974:   civ.property.listings = makePropertyListings(civ, rng);
975:   civ.supply = makeSupply(civ, rng);
976:   for (const seed of TECH_SEEDS) civ.tech.technologies.push(makeTech(civ, seed, rng));
977:   civ.tech.technologies.sort((a, b) => b.adoption - a.adoption);
978:   for (const tech of civ.tech.technologies.slice(0, 4)) if (tech.license.includes('open') && tech.adoption > 25) tech.standard = true;
979: 
980:   // Culture.
981:   for (const seed of CULTURE_SEEDS) civ.culture.organizations.push(makeCulture(civ, seed, rng));
982:   for (let i = 0; i < 12; i++) {
983:     const org = rng.pick(civ.culture.organizations);
984:     const country = civ.countries.find(c => c.id === org.countryId);
985:     civ.culture.games.push({ id: nextId(civ, 'game'), title: `${rng.pick(['Null', 'Signal', 'Harbor', 'Static', 'Open', 'Quiet', 'Cinder', 'Atlas'])} ${rng.pick(['Drift', 'Circuit', 'Garden', 'Protocol', 'Season', 'Machine', 'Shore', 'Archive'])}`, studioId: org.id, genre: rng.pick(['simulation', 'strategy', 'puzzle', 'narrative', 'sandbox', 'racing']), price: rng.int(0, 40), players: rng.int(200, 900000), rating: rng.float(2.6, 4.9), status: 'released', releasedWorld: game.worldMinutes - rng.int(30, 900) * DAY });
986:     civ.culture.music.push({ id: nextId(civ, 'music'), title: rng.pick(['Low Orbit', 'Paper Machines', 'Night Bus', 'Signal Lost', 'Quiet Infrastructure', 'Static Bloom']), artist: rng.pick(game.npcs)?.name || 'independent', countryId: country?.id || null, streams: rng.int(1000, 4200000), revenue: rng.int(40, 180000), releasedWorld: game.worldMinutes - rng.int(10, 500) * DAY });
987:   }
988:   for (const seed of rng.picks(['open-source', 'privacy', 'gaming', 'local news', 'digital labor', 'retro computing'], 5)) {
989:     civ.culture.communities.push({ id: nextId(civ, 'comm'), name: `${seed.replace(/\b\w/g, c => c.toUpperCase())} Circle`, topic: seed, members: rng.int(400, 280000), trust: rng.int(30, 90), countryId: rng.pick(civ.countries).id, status: 'active' });
990:   }
991:   for (let i = 0; i < 4; i++) civ.culture.esports.push({ id: nextId(civ, 'esport'), name: rng.pick(['Kiyosu Arc League', 'Rhine Simulation Cup', 'Sundar Open', 'Coral Invitational']), game: rng.pick(civ.culture.games).title, teams: rng.int(4, 32), prizePool: rng.int(20000, 2400000), audience: rng.int(12000, 1800000), status: 'active' });
992:   for (let i = 0; i < 4; i++) civ.culture.events.push({ id: nextId(civ, 'cevent'), name: rng.pick(['Open Bench Summit', 'Harborview Games Week', 'Greyhaven Digital Stage', 'Nordhavn Privacy Forum']), type: rng.pick(['conference', 'festival', 'tournament', 'exhibition']), cityId: rng.pick(civ.cities).id, attendance: rng.int(400, 90000), world: game.worldMinutes + rng.int(2, 120) * DAY, status: 'scheduled' });
993: 
994:   // Identities for every existing person.
995:   for (const npc of game.npcs || []) civ.identities.push(makeIdentity(game, civ, npc, rng));
996:   civ.player = {
997:     id: 'player', kind: 'player', handle: game.player.handle, name: game.player.name,
998:     countryId: 'novaria', cityId: 'meridian',
999:     professional: { score: 12, title: 'unproven', employerId: null, endorsements: 0, employmentHistory: [], verified: false },
1000:     social: { score: clamp(game.player.reputation, 0, 100), followers: 0, controversy: 0, communities: ['nullnet'] },
1001:     security: { score: 45, incidents: 0, credentials: [] },
1002:     financial: { score: 35, credit: 620, assets: Math.max(0, game.player.money) },
1003:     academic: { score: 8, publications: 0, citations: 0, field: null },
1004:     credentials: [], published: [], compliance: 82, updatedWorld: game.worldMinutes
1005:   };
1006: 
1007:   // Historical timeline before the player.
1008:   for (const [year, category, title, body] of HISTORY_SEEDS) {
1009:     civ.timeline.push({ id: nextId(civ, 'hist'), year, world: game.worldMinutes - (2026 - year) * YEAR, category, title, body, actors: [], countryId: null, major: true });
1010:   }
1011:   for (let i = 0; i < 18; i++) {
1012:     const country = rng.pick(civ.countries);
1013:     const year = rng.int(2015, 2025);
1014:     const fields = [['technology', 'A regional standards body updates its procurement rules'], ['economy', 'A mid-sized manufacturer restructures its supply chain'], ['law', 'A court clarifies liability for automated decisions'], ['culture', 'An independent studio finds an unexpected audience'], ['infrastructure', 'A city expands its fibre footprint']];
1015:     const [category, title] = rng.pick(fields);
1016:     civ.timeline.push({ id: nextId(civ, 'hist'), year, world: game.worldMinutes - (2026 - year) * YEAR, category, title, body: `${title} in ${country.name}. The effects were gradual and uneven.`, actors: [country.id], countryId: country.id, major: false });
1017:   }
1018:   civ.timeline.sort((a, b) => a.world - b.world);
1019:   bounded(civ.timeline, CAPS.timeline);
1020: 
1021:   civ.multiplayer = makeMultiplayer(game, civ);
1022: 
1023:   // A world already in motion.
1024:   const oldco = (game.companies || []).find(c => c.name === 'OldCo Systems');
1025:   if (oldco) {
1026:     civ.events.push({
1027:       id: nextId(civ, 'event'), category: 'infrastructure', title: 'OldCo migration remains incomplete',
1028:       body: 'The former hosting provider still answers on a small number of addresses. Regulators describe the estate as contained but unresolved.',
1029:       severity: 'moderate', status: 'active', startedWorld: game.worldMinutes - 90 * DAY,
1030:       durationWorld: 365 * DAY, countryId: 'novaria', actors: [oldco.id], effects: { cyberRisk: 4, mediaAttention: 2 },
1031:       headline: 'OldCo estate still partially online', resolved: null
1032:     });
1033:   }
1034:   civ.events.push({
1035:     id: nextId(civ, 'event'), category: 'supply', title: 'Semiconductor allocation remains tight',
1036:     body: 'Packaging capacity is improving, but advanced components are still allocated months ahead.',
1037:     severity: 'moderate', status: 'active', startedWorld: game.worldMinutes - 180 * DAY,
1038:     durationWorld: 240 * DAY, countryId: 'sakura', actors: [], effects: { hardwareIndex: 8, growth: -0.1 },
1039:     headline: 'Chip allocation still constrains hardware', resolved: null
1040:   });
1041: 
1042:   recomputeMetrics(civ, game);
1043:   game.civ = civ;
1044:   return civ;
1045: }
