1064:   civ.relations = civ.relations || { treaties: [], sanctions: [], negotiations: [], blocs: [] };
1065:   for (const key of ['treaties', 'sanctions', 'negotiations', 'blocs']) if (!Array.isArray(civ.relations[key])) civ.relations[key] = [];
