1067:   civ.education.player = civ.education.player || { knowledge: {}, credentials: [], studyHours: 0, enrolled: null };
1068:   civ.education.player.knowledge = civ.education.player.knowledge || {};
1069:   civ.education.player.credentials = civ.education.player.credentials || [];
1070:   civ.research = civ.research || { fields: RESEARCH_FIELDS.map(f => ({ id: f.id, name: f.name, code: f.code, level: 1, progress: 0, funding: 0, discoveries: [] })), labs: [], projects: [], discoveries: [] };
1071:   civ.research.fields = civ.research.fields || [];
1072:   civ.media = civ.media || { outlets: [], content: [], publicOpinion: {}, trends: [], playerPublished: [] };
1073:   civ.media.outlets = civ.media.outlets || [];
1074:   civ.media.content = civ.media.content || [];
1075:   civ.media.publicOpinion = civ.media.publicOpinion || {};
1076:   civ.media.trends = civ.media.trends || [];
1077:   civ.infrastructure = civ.infrastructure || { grids: [], fiber: [], dataCenters: [], logistics: [], outages: [] };
1078:   for (const key of ['grids', 'fiber', 'dataCenters', 'logistics', 'outages']) if (!Array.isArray(civ.infrastructure[key])) civ.infrastructure[key] = [];
1079:   civ.property = civ.property || { listings: [], owned: [], market: { index: 100, rentIndex: 100, vacancy: 7, lastUpdateWorld: game.worldMinutes } };
1080:   civ.property.listings = civ.property.listings || [];
1081:   civ.property.owned = civ.property.owned || [];
1082:   civ.supply = civ.supply || { materials: {}, components: {}, factories: [], warehouses: [], shipments: [], hardwareIndex: 100, energyIndex: 100, lastProductionWorld: game.worldMinutes };
1083:   civ.tech = civ.tech || { technologies: [], standards: [], lastReleaseWorld: game.worldMinutes };
1084:   civ.tech.technologies = civ.tech.technologies || [];
1085:   civ.culture = civ.culture || { organizations: [], games: [], music: [], communities: [], esports: [], events: [] };
1086:   for (const key of ['organizations', 'games', 'music', 'communities', 'esports', 'events']) if (!Array.isArray(civ.culture[key])) civ.culture[key] = [];
1087:   civ.player = civ.player || {
1088:     id: 'player', kind: 'player', handle: game.player.handle, name: game.player.name, countryId: 'novaria', cityId: 'meridian',
1089:     professional: { score: 12, title: 'unproven', employerId: null, endorsements: 0, employmentHistory: [], verified: false },
1090:     social: { score: 0, followers: 0, controversy: 0, communities: ['nullnet'] },
1091:     security: { score: 45, incidents: 0, credentials: [] }, financial: { score: 35, credit: 620, assets: 0 },
1092:     academic: { score: 8, publications: 0, citations: 0, field: null }, credentials: [], published: [], compliance: 82, updatedWorld: game.worldMinutes
1093:   };
1094:   civ.player.compliance = typeof civ.player.compliance === 'number' ? civ.player.compliance : 82;
1095:   civ.player.credentials = civ.player.credentials || [];
