2384: export function authorizeAction(game, actorId, action) {
2385:   const civ = ensureCivilization(game);
2386:   const mp = civ.multiplayer;
2387:   const actor = mp.players.find(p => p.id === actorId || p.handle === actorId);
2388:   if (!actor) return { ok: false, error: 'unknown actor' };
2389:   if (!actor.connected && action !== 'sync') return { ok: false, error: 'actor is disconnected' };
2390:   const allowed = mp.permissions[actor.role] || [];
2391:   if (!allowed.includes(action) && !allowed.includes('admin')) return { ok: false, error: `role ${actor.role} may not perform ${action}` };
2392:   const now = Date.now();
2393:   const key = `${actor.id}:${action}`;
2394:   mp.antiCheat.rate[key] = (mp.antiCheat.rate[key] || 0) + 1;
2395:   if (mp.antiCheat.rate[key] > 90) {
2396:     mp.antiCheat.rejected++;
2397:     return { ok: false, error: 'rate limit exceeded' };
2398:   }
2399:   return { ok: true, actor };
2400: }
