2402: export function validateLedger(game) {
2403:   const civ = ensureCivilization(game);
2404:   const mp = civ.multiplayer;
2405:   let prev = 'genesis';
2406:   for (const row of mp.ledger) {
2407:     const body = JSON.stringify({ actor: row.actor, action: row.action, amount: row.amount, memo: row.memo, world: row.world });
2408:     const expected = hash32(prev + body).toString(16).padStart(8, '0');
2409:     if (row.prev !== prev || row.hash !== expected) return { ok: false, brokenAt: row.id, expected, found: row.hash };
2410:     prev = row.hash;
2411:   }
2412:   return { ok: true, head: mp.ledgerHead, entries: mp.ledger.length, checked: mp.ledger.length };
2413: }
