2441: export function applyRemoteAction(game, actorId, action, payload = {}) {
2442:   const auth = authorizeAction(game, actorId, action);
2443:   if (!auth.ok) return auth;
2444:   const civ = ensureCivilization(game);
2445:   if (action === 'sync') {
2446:     civ.multiplayer.lastSync = Date.now();
2447:     return { ok: true, metrics: civ.metrics, snapshot: sharedSnapshot(game) };
2448:   }
2449:   if (action === 'trade' || action === 'property' || action === 'contracts' || action === 'company' || action === 'research' || action === 'publish') {
2450:     const row = recordLedger(game, { actor: auth.actor.handle, action, amount: payload.amount || 0, memo: payload.memo || action });
2451:     civ.multiplayer.lastSync = Date.now();
2452:     return { ok: true, accepted: row, authoritative: true, note: 'Action recorded. Transport adapters can relay this ledger entry to a shared server.' };
2453:   }
2454:   return { ok: false, error: `unsupported action ${action}` };
