import assert from 'node:assert/strict';
import { createGame, tickWorld, reviveGame, simulateOffline, worldClock } from './playground-check/src/world.js';
import { civilizationSummary, validateLedger, playerStudy, playerStartResearch, playerPublish, playerBuyProperty, playerSellProperty, playerRelocate, playerAdoptTech, educationFields } from './playground-check/src/civilization.js';

const game = createGame(123456);
assert.ok(game.civ && game.civ.countries.length > 0);
const initialClock = worldClock(game);
for (let i = 0; i < 5000; i++) tickWorld(game, 1);
assert.ok(game.civ.worldMinutes === game.worldMinutes);
assert.ok(game.companies.length <= 30 && game.npcs.length <= 420 && game.servers.length <= 180 && game.sites.length <= 220);
assert.ok(game.contracts.filter(c => c.status === 'open').length <= 60);
const saved = JSON.parse(JSON.stringify(game));
const restored = reviveGame(saved);
assert.equal(restored.civ.worldMinutes, restored.worldMinutes);
assert.deepEqual(validateLedger(restored).ok, true);

const baseline = restored.worldMinutes;
for (let day = 0; day < 1095; day++) tickWorld(restored, 1440);
assert.equal(restored.worldMinutes, baseline + 1095 * 1440);
assert.ok(restored.civ.timeline.length <= 280);
assert.ok(restored.civ.events.length <= 220);
assert.ok(restored.civ.multiplayer.ledger.length <= 400);
const afterYears = JSON.parse(JSON.stringify(restored));
reviveGame(afterYears);
assert.equal(afterYears.civ.worldMinutes, afterYears.worldMinutes);
assert.deepEqual(validateLedger(afterYears).ok, true);
const summary = civilizationSummary(afterYears);
assert.ok(summary.metrics && summary.countries > 0);
const offline = simulateOffline(afterYears, 60 * 60 * 1000);
assert.ok(offline && offline.worldMinutes > 0);
console.log(JSON.stringify({ initialClock, minutes: afterYears.worldMinutes, yearsSimulated: 3, companies: afterYears.companies.length, npcs: afterYears.npcs.length, servers: afterYears.servers.length, sites: afterYears.sites.length, openContracts: afterYears.contracts.filter(c => c.status === 'open').length, countries: summary.countries, timeline: afterYears.civ.timeline.length, events: afterYears.civ.events.length, offlineMinutes: offline.worldMinutes, ledger: validateLedger(afterYears) }, null, 2));

