    const vulnCount = security < 45 ? rng.int(2, 4) : security < 70 ? rng.int(0, 3) : rng.int(0, 1);
    const vulns = rng.picks(VULN_TYPES, vulnCount).map(v => makeVuln(rng, v.name, v.service));
    const ownerList = co ? (npcByCompany.get(co.id) || []) : [];
