  const country = playerCountry(game);
  return {
    civ, metrics: m, country, city: playerCity(game),
    year: m.year, courts: civ.courts.length, regulators: civ.regulators.length,
    activeLaws: civ.laws.filter(l => l.status === 'active').length,
