  ctx.print(`${place.label} · ${fmtDate(worldClock(g).date)} · index ${m.civilizationIndex}/100`, 'accent');
  ctx.print('');
  civLine(ctx, 'Population', fmtNum(m.population) + ' people');
  civLine(ctx, 'GDP', fmtBigMoney(m.gdp));
