import assert from 'node:assert/strict';
import { createGame, tickWorld, reviveGame, simulateOffline, worldClock } from './src/world.js';
import {
  civilizationSummary, validateLedger, careerSnapshot, jobMatch,
  playerApplyJob, playerInterviewJob, playerNegotiateJob, playerAcceptJob, playerQuitJob,
  ensureCivilization, CAPS
} from './src/civilization.js';

const CAP = { companies: 30, npcs: 420, servers: 240, sites: 220, contracts: 60 };

function snapshot(game) {
  return {
    companies: game.companies.length,
    npcs: game.npcs.length,
    servers: game.servers.length,
    sites: game.sites.length,
    openContracts: game.contracts.filter(c => c.status === 'open').length,
    news: game.news.length,
    feed: game.feed.length,
    timeline: game.civ.timeline.length,
    events: game.civ.events.length,
    identities: game.civ.identities.length,
    jobs: game.civ.jobs.length,
    content: game.civ.media.content.length,
    projects: game.civ.research.projects.length
  };
}

function assertCaps(s, label) {
  assert.ok(s.companies <= CAP.companies, `${label}: companies ${s.companies}`);
  assert.ok(s.npcs <= CAP.npcs, `${label}: npcs ${s.npcs}`);
  assert.ok(s.servers <= CAP.servers, `${label}: servers ${s.servers}`);
  assert.ok(s.sites <= CAP.sites, `${label}: sites ${s.sites}`);
  assert.ok(s.openContracts <= CAP.contracts, `${label}: open contracts ${s.openContracts}`);
  assert.ok(s.news <= 70, `${label}: news ${s.news}`);
  assert.ok(s.feed <= 80, `${label}: feed ${s.feed}`);
  assert.ok(s.timeline <= 280, `${label}: timeline ${s.timeline}`);
  assert.ok(s.events <= 220, `${label}: events ${s.events}`);
  assert.ok(s.jobs <= CAPS.jobs, `${label}: jobs ${s.jobs}`);
  assert.ok(s.content <= CAPS.content, `${label}: content ${s.content}`);
  assert.ok(s.projects <= CAPS.projects, `${label}: projects ${s.projects}`);
}

const game = createGame(123456);
assert.ok(game.civ && game.civ.countries.length >= 8);
const initialClock = worldClock(game);

// 1. Short open-ended play.
for (let i = 0; i < 5000; i++) tickWorld(game, 1);
assert.equal(game.civ.worldMinutes, game.worldMinutes);
let s = snapshot(game);
assertCaps(s, 'after 5k minutes');
console.log('after 5k minutes', JSON.stringify(s));

// 2. Save / reload round trip.
const restored = reviveGame(JSON.parse(JSON.stringify(game)));
assert.equal(restored.civ.worldMinutes, restored.worldMinutes);
assert.deepEqual(snapshot(restored), s);
assert.equal(validateLedger(restored).ok, true);

// 3. Determinism: same seed, same tick schedule -> same state.
const a = createGame(777);
const b = createGame(777);
for (let i = 0; i < 300; i++) tickWorld(a, 30);
for (let i = 0; i < 300; i++) tickWorld(b, 30);
assert.equal(a.worldMinutes, b.worldMinutes);
assert.equal(a.companies.length, b.companies.length);
assert.equal(a.civ.metrics.gdp, b.civ.metrics.gdp);
assert.equal(a.civ.timeline.length, b.civ.timeline.length);
console.log('determinism ok', a.civ.metrics.gdp.toFixed(2));

// 4. Long progression: three world years in daily ticks.
const baseline = restored.worldMinutes;
const t0 = Date.now();
for (let day = 0; day < 1095; day++) tickWorld(restored, 1440);
const elapsed = Date.now() - t0;
assert.equal(restored.worldMinutes, baseline + 1095 * 1440);
s = snapshot(restored);
assertCaps(s, 'after 3 years');
restored.civ.countries.forEach(c => {
  assert.ok(Number.isFinite(c.economy.gdp) && c.economy.gdp > 0, `gdp ${c.id}`);
  assert.ok(c.stability >= 10 && c.stability <= 98, `stability ${c.id}=${c.stability}`);
  assert.ok(c.unrest >= 0 && c.unrest <= 100, `unrest ${c.id}=${c.unrest}`);
  assert.ok(c.economy.growth >= -5 && c.economy.growth <= 9, `growth ${c.id}=${c.economy.growth}`);
  assert.ok(c.economy.inflation >= -1 && c.economy.inflation <= 18, `inflation ${c.id}`);
});
const hw = restored.civ.supply.hardwareIndex;
assert.ok(hw >= 55 && hw <= 320, `hardware index ${hw}`);
const cs = restored.civ.metrics;
assert.ok(cs.growth > -5 && cs.growth < 9, `metrics growth ${cs.growth}`);
assert.ok(cs.unemployment > 1 && cs.unemployment < 24, `metrics unemployment ${cs.unemployment}`);
assert.ok(cs.stability > 10, `metrics stability ${cs.stability}`);
console.log('after 3 years', JSON.stringify({ ms: elapsed, ...s, growth: +cs.growth.toFixed(2), unemployment: +cs.unemployment.toFixed(2), stability: +cs.stability.toFixed(2), hardware: hw }));

// 5. Save/reload after long run keeps all invariants.
const afterYears = reviveGame(JSON.parse(JSON.stringify(restored)));
assert.equal(afterYears.civ.worldMinutes, afterYears.worldMinutes);
assert.equal(validateLedger(afterYears).ok, true);
assert.deepEqual(snapshot(afterYears), s);

// 6. Offline simulation is bounded and produces a report.
const offline = simulateOffline(afterYears, 60 * 60 * 1000);
assert.ok(offline && offline.worldMinutes > 0);
assert.ok(offline.worldMinutes <= 7 * 1440, `offline ${offline.worldMinutes}`);
console.log('offline', JSON.stringify({ worldMinutes: offline.worldMinutes, before: offline.before, after: offline.after }));

// 7. Career loop: study -> apply -> interview -> negotiate/accept -> quit.
const career = createGame(4242);
const civ = ensureCivilization(career);
for (let i = 0; i < 720; i++) tickWorld(career, 60);
let job = civ.jobs.find(j => j.status === 'open');
assert.ok(job, 'the job market should publish roles');
// Force a strong candidate so the flow is deterministic.
civ.player.professional.score = 85;
civ.education.player.knowledge[job.field] = 90;
career.player.reputation = 70;
const match = jobMatch(career, job);
assert.ok(match >= 20, `match ${match}`);
const applied = playerApplyJob(career, job.id);
assert.ok(applied.ok, applied.error);
let outcome = playerInterviewJob(career, job.id);
for (let i = 0; i < 12 && outcome.ok && !outcome.offered && outcome.application.status === 'rejected'; i++) {
  civ.applications.length = 0;
  job.status = 'open';
  const retry = playerApplyJob(career, job.id);
  assert.ok(retry.ok, retry.error);
  outcome = playerInterviewJob(career, job.id);
}
if (outcome.ok && outcome.offered) {
  const offer = outcome.offer;
  const negotiated = playerNegotiateJob(career, job.id, Math.round(offer * 1.1));
  const finalOffer = negotiated.ok && negotiated.accepted ? negotiated.offer : (civ.applications.find(a => a.jobId === job.id)?.offerSalary ?? offer);
  const accepted = playerAcceptJob(career, job.id);
  assert.ok(accepted.ok, accepted.error);
  assert.equal(civ.player.professional.employerId, job.companyId);
  assert.equal(civ.player.professional.salary, finalOffer);
  assert.equal(job.status, 'filled');
  // Payroll must credit the player after a world month.
  const before = career.player.money;
  for (let i = 0; i < 40; i++) tickWorld(career, 1440);
  assert.ok(career.player.money > before, `salary not paid: ${before} -> ${career.player.money}`);
  const quit = playerQuitJob(career);
  assert.ok(quit.ok, quit.error);
  assert.equal(civ.player.professional.employerId, null);
  assert.ok(civ.player.professional.employmentHistory.some(h => h.untilWorld != null));
  const snap = careerSnapshot(career);
  assert.ok(Array.isArray(snap.jobs));
  console.log('career ok', JSON.stringify({ match, offer: finalOffer, money: career.player.money, history: snap.professional.employmentHistory.length }));
} else {
  console.log('career: interview rejected (rng) — acceptance path covered by forced run below');
  // Deterministic acceptance path with a guaranteed offer.
  civ.applications.length = 0;
  job.status = 'open';
  playerApplyJob(career, job.id);
  const app = civ.applications[0];
  app.status = 'offered';
  app.offerSalary = job.salary;
  const accepted = playerAcceptJob(career, job.id);
  assert.ok(accepted.ok, accepted.error);
  const before = career.player.money;
  for (let i = 0; i < 40; i++) tickWorld(career, 1440);
  assert.ok(career.player.money > before);
  assert.ok(playerQuitJob(career).ok);
  console.log('career forced ok', JSON.stringify({ money: career.player.money }));
}

// 8. Large offline workload after long progression stays capped.
const heavy = createGame(999);
for (let i = 0; i < 2000; i++) tickWorld(heavy, 60);
const heavyBefore = heavy.worldMinutes;
const heavyOffline = simulateOffline(heavy, 5 * 24 * 3600 * 1000);
assert.ok(heavyOffline && heavyOffline.worldMinutes > 0);
assert.ok(heavy.worldMinutes >= heavyBefore);
assertCaps(snapshot(heavy), 'after heavy offline');

console.log('\nALL CHECKS PASSED');

