import assert from 'node:assert/strict';
import { createGame, tickWorld } from './src/world.js';
import { execute, commandNames } from './src/shell.js';

function makeHarness(seed = 20260101) {
  const game = createGame(seed);
  for (let i = 0; i < 720; i++) tickWorld(game, 30);
  const app = { game, windows: new Map(), openWindow() {}, save() {} };
  const lines = [];
  const term = {
    localFS: game.fs, cwd: '/home/operator', prevCwd: '/home/operator',
    history: [], histIndex: 0, pending: null, remote: null, remoteRoot: null,
    user: 'operator', host: 'voidbox', env: {},
    print(text = '', cls = '') { lines.push({ text: String(text), cls }); },
    async run(line) {
      lines.length = 0;
      await execute(app, term, line);
      return lines.map(l => l.text).join('\n');
    }
  };
  return { game, app, term, lines };
}

const needed = ['civ', 'ls', 'cat', 'whoami', 'neofetch', 'market', 'contracts', 'mail', 'news', 'map', 'help', 'save'];
for (const name of needed) assert.ok(commandNames().includes(name), `missing command ${name}`);

const h = makeHarness();
const out = {};

// Legacy commands must still work.
for (const cmd of ['whoami', 'ls', 'neofetch', 'market', 'contracts', 'news', 'map']) {
  const text = await h.term.run(cmd);
  assert.ok(!/command not found|internal simulation error/i.test(text), `${cmd}: ${text.slice(0, 200)}`);
  out[cmd] = text.split('\n').length;
}

// Civilization overview and subcommands.
const civOverview = await h.term.run('civ');
assert.ok(!/command not found|internal simulation error/i.test(civOverview), civOverview);
assert.ok(/CIVILIZATION|WORLD/i.test(civOverview), 'civ overview should print headings');
out.civ = civOverview.split('\n').length;

const subcommands = [
  'civ world', 'civ geography', 'civ society', 'civ education', 'civ research',
  'civ business', 'civ industry', 'civ science', 'civ media', 'civ culture',
  'civ politics', 'civ law', 'civ life', 'civ infrastructure', 'civ economy',
  'civ events', 'civ history', 'civ property', 'civ jobs', 'civ career',
  'civ mp', 'civ tech', 'civ supply', 'civ metrics'
];
for (const cmd of subcommands) {
  const text = await h.term.run(cmd);
  assert.ok(!/command not found|internal simulation error|is not a recognized subcommand/i.test(text), `${cmd}: ${text.slice(0, 240)}`);
}
console.log('subcommands ok', subcommands.length);

// Study, research, publish, property, relocate, lobby.
const study = await h.term.run('civ study programming 4');
assert.ok(!/internal simulation error/i.test(study), study);
const research = await h.term.run('civ research ai');
assert.ok(!/internal simulation error/i.test(research), research);
const publish = await h.term.run('civ publish "Test headline about networks"');
assert.ok(!/internal simulation error/i.test(publish), publish);
const lobby = await h.term.run('civ lobby');
assert.ok(!/internal simulation error/i.test(lobby), lobby);
const relocate = await h.term.run('civ relocate');
assert.ok(!/internal simulation error/i.test(relocate), relocate);
const events = await h.term.run('civ events all');
assert.ok(!/internal simulation error/i.test(events), events);
const history = await h.term.run('civ history network');
assert.ok(!/internal simulation error/i.test(history), history);

// Full career loop through the shell.
const jobsText = await h.term.run('civ jobs');
assert.ok(/JOB MARKET/i.test(jobsText), jobsText);
const jobs = h.game.civ.jobs.filter(j => j.status === 'open');
assert.ok(jobs.length > 0, 'no open jobs');
const job = jobs[0];
h.game.civ.player.professional.score = 88;
h.game.civ.education.player.knowledge[job.field] = 92;
h.game.player.reputation = 75;
const applyText = await h.term.run(`civ apply ${job.id}`);
assert.ok(/Applied to/i.test(applyText), applyText);
let interviewText = await h.term.run(`civ interview ${job.id}`);
for (let i = 0; i < 10 && /declined your application/i.test(interviewText); i++) {
  h.game.civ.applications.length = 0;
  job.status = 'open';
  await h.term.run(`civ apply ${job.id}`);
  interviewText = await h.term.run(`civ interview ${job.id}`);
}
if (/Offer:/i.test(interviewText)) {
  const offerMatch = interviewText.match(/\$([\d,]+)\/yr/);
  const offer = Number(offerMatch[1].replace(/,/g, ''));
  const negotiateText = await h.term.run(`civ negotiate ${job.id} ${Math.round(offer * 1.08)}`);
  assert.ok(/agreed to|withdrew the offer/i.test(negotiateText), negotiateText);
  const acceptText = await h.term.run(`civ accept ${job.id}`);
  if (/now work at/i.test(acceptText)) {
    assert.ok(h.game.civ.player.professional.employerId, 'not employed after accept');
    const careerText = await h.term.run('civ career');
    assert.ok(/since|Professional score/i.test(careerText), careerText);
    const before = h.game.player.money;
    for (let i = 0; i < 35; i++) tickWorld(h.game, 1440);
    assert.ok(h.game.player.money > before, 'payroll did not credit player');
    const quitText = await h.term.run('civ quit');
    assert.ok(/Left /i.test(quitText), quitText);
    out.career = 'full';
  } else {
    out.career = 'accept-rejected';
  }
} else {
  out.career = interviewText.slice(0, 120);
}

// Multiplayer join/validate/leave.
const join = await h.term.run('civ mp join operator1 Operator One');
assert.ok(/joined shared world/i.test(join), join);
const validate = await h.term.run('civ mp validate');
assert.ok(/Ledger valid|Ledger broken/i.test(validate), validate);
const leave = await h.term.run('civ mp leave operator1');
assert.ok(/disconnected/i.test(leave), leave);

// Save migration: strip the civ layer and revive through normal load path.
const stripped = JSON.parse(JSON.stringify(h.game));
delete stripped.civ;
delete stripped.growth;
const { reviveGame } = await import('./src/world.js');
const revived = reviveGame(stripped);
assert.ok(revived.civ && revived.civ.countries.length >= 8, 'legacy save did not gain civilization');
assert.ok(revived.civ.jobs.length >= 0);
assert.equal(revived.civ.worldMinutes, revived.worldMinutes);
const okText = await (async () => {
  const h2 = { game: revived, term: { ...h.term, print: (t, c) => h.lines.push({ text: String(t), cls: c }) } };
  h.lines.length = 0;
  await execute(h2, h2.term, 'civ');
  return h.lines.map(l => l.text).join('\n');
})();
assert.ok(!/command not found|internal simulation error/i.test(okText), okText);

console.log(JSON.stringify(out, null, 2));
console.log('SHELL CHECKS PASSED');

