1862:   bounded(civ.research.projects, CAPS.projects);
1863:   // Existing projects can be revived by renewed funding.
1864:   for (const project of civ.research.projects) {
1865:     if (project.status === 'stalled' && project.funding >= project.fundingNeeded * .6 && rng.chance(.06)) {
1866:       project.status = 'active';
1867:       project.progress = Math.max(project.progress, 58);
1868:       emit(events, 'feed', `${project.labName} resumes ${project.fieldName} work after renewed funding.`, { kind: 'good' });
1869:     }
1870:   }
1871: }
