1873: function applyDiscovery(game, civ, discovery, rng, events) {
1874:   const fieldState = civ.research.fields.find(f => f.id === discovery.field);
1875:   if (fieldState) fieldState.funding += rng.int(20000, 220000);
1876:   for (const [sector, weight] of Object.entries(discovery.impact || {})) {
1877:     const companies = (game.companies || []).filter(c => String(c.sector).toLowerCase().includes(sector) || sector === 'manufacturing' && c.sector === 'manufacturing');
1878:     for (const co of companies.slice(0, 4)) {
1879:       co.rep = clamp((co.rep || 50) + Math.round(weight / 2), 0, 100);
1880:       co.funds += Math.round(co.revenue * weight * .01);
1881:     }
1882:   }
1883:   // Tiers 2 and 3 can produce a new technology, never an impossible one.
1884:   if (discovery.tier >= 2) {
1885:     const categoryByField = { cs: 'devtools', ai: 'ai', robotics: 'framework', semiconductors: 'cpu', cryptography: 'security', quantum: 'devtools', telecom: 'networking', materials: 'cpu', energy: 'networking', biotech: 'devtools' };
1886:     const category = categoryByField[discovery.field] || 'devtools';
1887:     const lab = civ.research.labs.find(l => l.id === discovery.labId);
1888:     const country = civ.countries.find(c => c.id === discovery.countryId);
1889:     const tech = {
1890:       id: nextId(civ, 'tech'), name: discovery.name, category,
1891:       vendorName: lab?.name || country?.name || 'Independent consortium', license: rng.chance(.35) ? 'open-source' : 'source-available',
1892:       version: '1.0', adoption: rng.int(2, 12), compatibility: rng.pick([['x86', 'arm'], ['linux'], ['cloud'], ['portable']]),
1893:       releasedWorld: civ.worldMinutes, documentation: rng.int(20, 62), security: rng.int(35, 78), ecosystem: rng.int(8, 42),
1894:       priceIndex: rng.int(45, 130), status: 'active', standard: false,
1895:       originDiscoveryId: discovery.id, competitors: []
1896:     };
1897:     civ.tech.technologies.push(tech);
1898:     civilRecordTech(civ, tech, events);
1899:   }
1900: }
