1908: /* -------- property market and daily rent -------- */
1909: function propertyCadence(game, civ, rng, events) {
1910:   const market = civ.property.market;
1911:   market.index = clamp(market.index + (rng.next() - .48) * .7 + (civ.metrics.growth - civ.metrics.inflation) * .03, 55, 220);
1912:   market.rentIndex = clamp(market.rentIndex + (rng.next() - .5) * .6 + (civ.metrics.growth - 2) * .03, 45, 240);
1913:   market.vacancy = clamp(market.vacancy + (rng.next() - .52) * .3, 1, 32);
1914:   market.lastUpdateWorld = civ.worldMinutes;
1915: 
1916:   for (const listing of civ.property.listings) {
1917:     if (listing.status !== 'available') continue;
1918:     const city = civ.cities.find(c => c.id === listing.cityId);
1919:     if (!city) continue;
1920:     const target = Math.round(listing.price * (1 + (market.index / 100 - 1) * .04 + (rng.next() - .5) * .01));
1921:     listing.price = Math.max(1000, target);
1922:     listing.rent = Math.max(20, Math.round(listing.price * (market.rentIndex / 100) * .004 / 12));
1923:   }
1924: 
1925:   // NPCs move when they can afford local housing and employment is stable.
1926:   if (civ.property.owned.length < CAPS.owned && rng.chance(.22)) {
1927:     const city = pickWeighted(rng, civ.cities, c => Math.max(1, c.population / 100000));
1928:     const buyer = rng.pick(game.npcs || []);
1929:     if (buyer && city) {
1930:       const listing = civ.property.listings.find(l => l.cityId === city.id && l.status === 'available' && l.type === 'apartment');
1931:       if (listing) {
1932:         listing.status = 'owned';
1933:         listing.ownerId = buyer.id;
1934:         listing.ownerName = buyer.handle;
1935:         civ.property.owned.push({ ...listing, purchasedWorld: civ.worldMinutes, occupancy: 'owner', rentPaid: 0 });
1936:       }
1937:     }
1938:   }
1939: 
1940:   // Player property costs and income are part of the persistent economy.
1941:   for (const property of civ.property.owned.filter(p => p.ownerId === 'player')) {
1942:     const city = civ.cities.find(c => c.id === property.cityId);
1943:     const country = civ.countries.find(c => c.id === property.countryId);
1944:     const maintenance = Math.max(0, Math.round((property.maintenance || property.price * .008 / 12) / 30));
1945:     const tax = Math.max(0, Math.round(property.price * (country?.tax.vat || 8) / 100 / 365));
1946:     const rentIncome = property.occupancy === 'rented' ? Math.round((property.rent || 0) / 30) : 0;
1947:     const net = rentIncome - maintenance - tax;
1948:     if (net !== 0) {
1949:       game.player.money += net;
1950:       game.player.transactions.unshift({ time: Date.now(), amount: net, memo: `property ${property.label} · ${city?.name || property.cityId}`, balance: game.player.money });
1951:       if (game.player.transactions.length > 120) game.player.transactions.length = 120;
1952:       if (net > 0) game.stats.earned += net; else game.stats.spent += Math.abs(net);
1953:     }
1954:     if (game.player.money < 0 && rng.chance(.08)) {
1955:       game.player.heat = clamp(game.player.heat + 1, 0, 100);
1956:       pushMail(game, 'notice', 'Property charge unpaid', `A property charge for ${property.label} could not be settled. Repeated arrears may affect your standing with the ${country?.name || 'local'} property registry.`);
1957:     }
1958:   }
1959: 
1960:   // New construction appears slowly.
1961:   if (civ.property.listings.filter(l => l.status === 'available').length < 30 && rng.chance(.18)) {
1962:     const city = rng.pick(civ.cities);
1963:     const [type, label, base, rentYield] = rng.pick(PROPERTY_TYPES);
1964:     civ.property.listings.push({
1965:       id: nextId(civ, 'prop'), type, label, cityId: city.id, countryId: city.countryId,
1966:       price: Math.round(base * city.costIndex * (market.index / 100) * rng.float(.8, 1.2) / 1000) * 1000,
1967:       rent: Math.round(base * city.costIndex * (market.rentIndex / 100) * rentYield / 12),
1968:       maintenance: Math.round(base * city.costIndex * .008 / 12),
1969:       taxRate: (civ.countries.find(c => c.id === city.countryId)?.tax.vat || 8) / 100,
1970:       ownerId: null, ownerName: 'market', status: 'available', quality: rng.int(35, 96),
1971:       built: worldYear(civ), listedWorld: civ.worldMinutes
1972:     });
1973:   }
1974:   bounded(civ.property.listings, CAPS.listings);
1975:   bounded(civ.property.owned, CAPS.owned);
1976: }
