1979: function educationCadence(game, civ, rng, events) {
1980:   for (const inst of civ.education.institutions) {
1981:     if (rng.chance(.12)) inst.quality = clamp(inst.quality + rng.int(-1, 1), 20, 98);
1982:     if (rng.chance(.08)) inst.enrolled = (inst.enrolled || 0) + rng.int(10, 200);
1983:     inst.researchOutput = clamp(inst.researchOutput + rng.int(-1, 1), 5, 98);
1984:   }
1985:   // A bounded number of NPCs enroll and complete courses.
1986:   if (civ.education.enrollments.filter(e => e.status === 'studying').length < 24 && rng.chance(.35)) {
1987:     const npc = rng.pick(game.npcs || []);
1988:     const course = rng.pick(civ.education.courses);
1989:     if (npc && course) {
1990:       civ.education.enrollments.push({ id: nextId(civ, 'enroll'), npcId: npc.id, handle: npc.handle, courseId: course.id, courseName: `${course.fieldName} · ${course.level}`, startedWorld: civ.worldMinutes, progress: rng.int(0, 35), status: 'studying' });
1991:     }
1992:   }
1993:   for (const enrollment of civ.education.enrollments) {
1994:     if (enrollment.status !== 'studying') continue;
1995:     const course = civ.education.courses.find(c => c.id === enrollment.courseId);
1996:     enrollment.progress = clamp(enrollment.progress + rng.int(1, 6), 0, 100);
1997:     if (enrollment.progress >= 100) {
1998:       enrollment.status = 'completed';
1999:       const npc = game.npcs.find(n => n.id === enrollment.npcId);
2000:       if (npc) {
2001:         npc.skill = clamp((npc.skill || 50) + rng.int(1, 4), 0, 99);
2002:         npc.rep = clamp((npc.rep || 40) + (course?.quality > 70 ? 1 : 0), 0, 100);
2003:         const identity = civ.identities.find(i => i.id === npc.id);
2004:         if (identity) {
2005:           identity.professional.score = clamp(identity.professional.score + rng.int(1, 4), 0, 100);
2006:           identity.credentials.push({ name: course?.certification || 'Course certificate', issuer: course?.institutionName || 'online provider', world: civ.worldMinutes });
2007:           bounded(identity.credentials, 12);
2008:         }
2009:       }
2010:       emit(events, 'feed', `@${enrollment.handle} completed ${enrollment.courseName}.`, { kind: 'info' });
2011:     }
2012:   }
2013:   bounded(civ.education.enrollments, 120);
2014:   // Keep a rotating catalog without unbounded growth.
2015:   if (civ.education.courses.length < 36 && rng.chance(.12)) {
2016:     const field = rng.pick(EDU_FIELDS);
2017:     const inst = rng.pick(civ.education.institutions);
2018:     civ.education.courses.push(makeCourse(civ, field, inst, civ.countries.find(c => c.id === inst.countryId), rng));
2019:   }
