2022: /* -------- employment market and careers -------- */
2023: function makeJobPosting(game, civ, rng) {
2024:   const employers = (game.companies || []).filter(c => c.status === 'operating' && c.ownerType !== 'player');
2025:   if (!employers.length) return null;
2026:   const company = pickWeighted(rng, employers, c => Math.max(500, c.funds || 0));
2027:   const sector = String(company.sector || '').toLowerCase();
2028:   const eligible = CAREER_ROLES.filter(role => role.sectors.some(s => sector.includes(s)));
2029:   const role = rng.pick(eligible.length ? eligible : CAREER_ROLES);
2030:   const level = pickWeighted(rng, JOB_LEVELS, l => l.id === 'mid' ? 42 : l.id === 'junior' ? 30 : l.id === 'senior' ? 20 : 8);
2031:   const country = countryForCompany(civ, company) || rng.pick(civ.countries);
2032:   const countryCities = civ.cities.filter(c => c.countryId === country.id);
2033:   const city = rng.pick(countryCities.length ? countryCities : civ.cities);
2034:   const remote = !!role.remote && rng.chance(.45);
2035:   const salary = Math.max(18000, Math.round(rng.int(role.salary[0], role.salary[1]) * level.multiplier * (country.costIndex * .7 + .3) / 500) * 500);
2036:   return {
2037:     id: nextId(civ, 'job'), companyId: company.id, companyName: company.name,
2038:     title: role.title, roleId: role.id, field: role.field, level: level.id, levelName: level.name,
2039:     salary, remote, countryId: country.id, cityId: city?.id || null,
2040:     requirements: {
2041:       professional: clamp(level.professional + rng.int(-4, 6), 5, 95),
2042:       knowledge: clamp(level.knowledge + rng.int(-3, 5), 3, 95),
2043:       years: level.years
2044:     },
2045:     status: 'open', postedWorld: civ.worldMinutes, expiresWorld: civ.worldMinutes + rng.int(24, 50) * DAY,
2046:     applicants: 0, filledBy: null, filledWorld: null,
2047:     description: `${company.name} is hiring a ${level.name.toLowerCase()} ${role.title.toLowerCase()}${remote ? ' (remote)' : ` in ${city?.name || country.name}`}.`
2048:   };
2049: }
