2051: export function jobMatch(game, job) {
2052:   if (!job) return 0;
2053:   const civ = ensureCivilization(game);
2054:   const professional = civ.player.professional?.score || 0;
2055:   const knowledge = civ.education.player.knowledge?.[job.field] || 0;
2056:   const credential = civ.education.player.credentials?.some(c => c.field === job.field) ? 2 : 0;
2057:   const reputation = clamp(game.player.reputation || 0, 0, 100);
2058:   const profRatio = professional / Math.max(1, job.requirements?.professional || 1);
2059:   const knowRatio = (knowledge + 2) / Math.max(1, job.requirements?.knowledge || 1);
2060:   return Math.round(clamp((profRatio * .58 + knowRatio * .42) * 50 + reputation * .12 + credential, 0, 100));
2061: }
