2063: function hireNpcForJob(game, civ, job, npc, rng) {
2064:   job.status = 'filled';
2065:   job.filledBy = npc.id;
2066:   job.filledWorld = civ.worldMinutes;
2067:   const previous = npc.company;
2068:   npc.companyId = job.companyId;
2069:   npc.company = job.companyName;
2070:   npc.role = job.title;
2071:   npc.activity = 'working';
2072:   const identity = civ.identities.find(i => i.id === npc.id);
2073:   if (identity) {
2074:     const prof = identity.professional || (identity.professional = { score: 40, title: npc.role, employerId: null, endorsements: 0, employmentHistory: [], verified: false });
2075:     prof.employerId = job.companyId;
2076:     prof.title = job.title;
2077:     prof.score = clamp((prof.score || 40) + 2, 0, 100);
2078:     prof.employmentHistory = prof.employmentHistory || [];
2079:     prof.employmentHistory.push({ companyId: job.companyId, employerName: job.companyName, role: job.title, salary: job.salary, sinceWorld: civ.worldMinutes });
2080:     bounded(prof.employmentHistory, 16);
2081:   }
2082:   for (const app of civ.applications) {
2083:     if (app.jobId === job.id && app.status !== 'offered' && app.status !== 'accepted') app.status = 'closed';
2084:   }
2085:   if (rng.chance(.22)) {
2086:     recordTimeline(civ, 'labor', `@${npc.handle} joins ${job.companyName}`, `${npc.handle} moves from ${previous || 'independent work'} into a ${job.levelName.toLowerCase()} ${job.title.toLowerCase()} role.`, { actors: [npc.id, job.companyId], major: false });
2087:   }
2088:   emitListForJobs(game, `${job.companyName} hired @${npc.handle} as ${job.title}.`);
2089:   return true;
2090: }
