2098: function jobsCadence(game, civ, rng, events) {
2099:   for (const job of civ.jobs) {
2100:     if (job.status === 'open' && civ.worldMinutes > job.expiresWorld) job.status = 'expired';
2101:   }
2102:   const open = civ.jobs.filter(j => j.status === 'open').length;
2103:   if (open < CAPS.jobs && rng.chance(.7)) {
2104:     const job = makeJobPosting(game, civ, rng);
2105:     if (job) {
2106:       civ.jobs.push(job);
2107:       if (rng.chance(.08)) emit(events, 'feed', `${job.companyName} posted a ${job.title} role.`, { kind: 'info' });
2108:     }
2109:   }
2110:   for (const job of civ.jobs) {
2111:     if (job.status !== 'open') continue;
2112:     if (civ.worldMinutes - job.postedWorld < 3 * DAY) continue;
2113:     if (!rng.chance(.055)) continue;
2114:     const candidates = (game.npcs || []).filter(n => !n.key || rng.chance(.12)).filter(n => (n.skill || 40) >= job.requirements.professional - 14);
2115:     if (!candidates.length) continue;
2116:     const npc = rng.pick(candidates);
2117:     if (npc.companyId === job.companyId) {
2118:       job.status = 'filled';
2119:       job.filledBy = npc.id;
2120:       job.filledWorld = civ.worldMinutes;
2121:       continue;
2122:     }
2123:     hireNpcForJob(game, civ, job, npc, rng);
2124:   }
2125:   bounded(civ.jobs, CAPS.jobs);
2126:   bounded(civ.applications, CAPS.applications);
2127: }
