2129: /* -------- physical infrastructure and world effects -------- */
2130: function infrastructureCadence(game, civ, rng, events) {
2131:   const outageChance = .035;
2132:   for (const grid of civ.infrastructure.grids) {
2133:     if (rng.chance(outageChance * (1 + (100 - grid.reliability) / 180))) {
2134:       const duration = rng.int(20, 240);
2135:       const outage = { id: nextId(civ, 'outage'), kind: 'power', targetId: grid.id, cityId: grid.cityId, countryId: grid.countryId, startedWorld: civ.worldMinutes, endsWorld: civ.worldMinutes + duration, severity: rng.pick(['minor', 'major']), status: 'active' };
2136:       civ.infrastructure.outages.push(outage);
2137:       grid.status = 'degraded';
2138:       const city = civ.cities.find(c => c.id === grid.cityId);
2139:       if (city) city.utilities.power = clamp(city.utilities.power - rng.int(8, 25), 5, 99);
2140:       applyOutageToServers(game, civ, outage, events);
2141:       emit(events, 'feed', `Power disruption in ${city?.name || grid.cityId}. Data center operators are switching to backup capacity.`, { kind: 'warn' });
2142:       recordTimeline(civ, 'infrastructure', `Power disruption in ${city?.name || grid.cityId}`, 'A grid fault interrupted industrial and data-center load. Backup systems covered part of the demand.', { countryId: grid.countryId, major: false });
2143:     }
2144:   }
2145:   for (const fiber of civ.infrastructure.fiber) {
2146:     if (rng.chance(.018 * (1 + (100 - fiber.redundancy) / 220))) {
2147:       const duration = rng.int(30, 360);
2148:       const outage = { id: nextId(civ, 'outage'), kind: 'fiber', targetId: fiber.id, cityId: null, countryId: fiber.countryId, startedWorld: civ.worldMinutes, endsWorld: civ.worldMinutes + duration, severity: 'major', status: 'active' };
2149:       civ.infrastructure.outages.push(outage);
2150:       fiber.status = 'degraded';
2151:       fiber.latency = clamp(fiber.latency + rng.int(12, 70), 2, 260);
2152:       applyOutageToServers(game, civ, outage, events);
2153:       const country = civ.countries.find(c => c.id === fiber.countryId);
2154:       emit(events, 'news', `Fibre disruption raises latency in ${country?.name || fiber.countryId}`, { body: 'A damaged route is forcing traffic through alternatives. Operators report elevated latency and intermittent packet loss.', source: 'The Packet' });
2155:     }
2156:   }
2157:   for (const outage of civ.infrastructure.outages) {
2158:     if (outage.status !== 'active' || civ.worldMinutes < outage.endsWorld) continue;
2159:     outage.status = 'resolved';
2160:     const grid = civ.infrastructure.grids.find(g => g.id === outage.targetId);
2161:     if (grid) grid.status = 'nominal';
2162:     const fiber = civ.infrastructure.fiber.find(f => f.id === outage.targetId);
2163:     if (fiber) { fiber.status = 'nominal'; fiber.latency = Math.max(2, fiber.latency - 18); }
2164:     restoreServersAfterOutage(game, civ, outage, events);
2165:     emit(events, 'feed', `Infrastructure incident resolved (${outage.kind}).`, { kind: 'good' });
2166:   }
2167:   bounded(civ.infrastructure.outages, CAPS.outages);
2168: }
