2170: function applyOutageToServers(game, civ, outage, events) {
2171:   const affected = (game.servers || []).filter(s => {
2172:     if (outage.kind === 'power') {
2173:       const dc = civ.infrastructure.dataCenters.find(d => d.cityId === outage.cityId);
2174:       return dc && (s.region === dc.region || s.id === dc.id);
2175:     }
2176:     return s.region === outage.countryId || civ.cities.find(c => c.id === outage.cityId)?.region === s.region;
2177:   });
2178:   for (const server of affected.slice(0, 40)) {
2179:     server.civOutage = outage.id;
2180:     server.civLatency = clamp((server.latency || 20) + (outage.severity === 'major' ? rngLatency(outage) : 8), 2, 400);
2181:     if (outage.kind === 'power' && outage.severity === 'major') server.status = 'degraded';
2182:     server.traffic = Math.max(0, Math.round((server.traffic || 0) * .82));
2183:     if (server.owned) emit(events, 'feed', `${server.host} is affected by a ${outage.kind} incident.`, { kind: 'warn' });
2184:   }
2185: }
2186: 
2187: function rngLatency(outage) {
2188:   return 20 + (hash32(outage.id) % 90);
2189: }
2190: 
2191: function restoreServersAfterOutage(game, civ, outage, events) {
2192:   for (const server of game.servers || []) {
2193:     if (server.civOutage !== outage.id) continue;
2194:     server.civOutage = null;
2195:     server.civLatency = Math.max(4, Math.round((server.civLatency || 20) * .55));
2196:     if (server.status === 'degraded' && !server.civHold) server.status = 'online';
2197:     if (server.owned) emit(events, 'feed', `${server.host} recovered after the ${outage.kind} incident.`, { kind: 'good' });
2198:   }
2199: }
