2212: function resolveWorldEvent(game, civ, event, rng, events) {
2213:   if (event.id === 'infrastructure-project' || event.category === 'infrastructure' && event.title.includes('cable')) {
2214:     for (const country of civ.countries) country.internet.speed = Math.round(country.internet.speed * 1.02);
2215:     emit(events, 'feed', 'A long-running infrastructure project reaches completion. Regional capacity improves.', { kind: 'good' });
