2222:       fiber.status = 'nominal';
2223:       fiber.latency = Math.max(2, fiber.latency * .8);
2224:     }
2225:   }
2226:   recordTimeline(civ, event.category, `${event.title} — resolved`, event.body, { countryId: event.countryId, actors: event.actors, major: false });
2227:   emit(events, 'feed', `${event.title} has resolved.`, { kind: 'info' });
