2686: export function playerApplyJob(game, query) {
2687:   const civ = ensureCivilization(game);
2688:   const prof = civ.player.professional;
2689:   if (prof.employerId) return { ok: false, error: `You already work at ${prof.employerName || 'an employer'}. Quit first: civ quit` };
2690:   const job = findOpenJob(civ, query);
2691:   if (!job) return { ok: false, error: 'No open role matches that. Try: civ jobs' };
2692:   const existing = civ.applications.find(a => a.jobId === job.id);
2693:   if (existing && ['applied', 'interview', 'offered'].includes(existing.status)) {
2694:     return { ok: false, error: `You already have an application for ${job.title} (${existing.status}). Interview: civ interview ${job.id}` };
2695:   }
2696:   const match = jobMatch(game, job);
2697:   if (match < 20) {
2698:     const fieldName = EDU_FIELDS.find(f => f.id === job.field)?.name || job.field;
2699:     return { ok: false, error: `Your application is not competitive (${match}% match). Study ${fieldName.toLowerCase()} or build professional experience first.` };
2700:   }
2701:   const app = existing || { id: nextId(civ, 'app'), jobId: job.id, appliedWorld: civ.worldMinutes };
2702:   app.status = 'applicants';
2703:   app.match = match;
2704:   app.appliedWorld = civ.worldMinutes;
2705:   app.interviewWorld = null;
2706:   app.offerSalary = null;
2707:   if (!existing) civ.applications.push(app);
2708:   job.applicants = (job.applicants || 0) + 1;
2709:   emitPlayerFeed(game, `Applied to ${job.title} at ${job.companyName} (${match}% match).`, 'info');
2710:   return { ok: true, application: app, job, match };
2711: }
