2713: export function playerInterviewJob(game, query) {
2714:   const civ = ensureCivilization(game);
2715:   const app = findApplication(civ, query);
2716:   if (!app) return { ok: false, error: 'No application matches that. Apply first: civ apply <job>' };
2717:   if (!['applicants', 'applied', 'interview'].includes(app.status)) return { ok: false, error: `That application is already ${app.status}.` };
2718:   const job = civ.jobs.find(j => j.id === app.jobId);
2719:   if (!job || job.status !== 'open') {
2720:     app.status = 'closed';
2721:     return { ok: false, error: 'That role is no longer open.' };
2722:   }
2723:   const rng = makeRng((game.seed ^ hash32(app.id) ^ (game.tickCount * 97) ^ 0x51ab) >>> 0);
2724:   const fieldCredential = civ.education.player.credentials.some(c => c.field === job.field);
2725:   const reputation = clamp(game.player.reputation || 0, 0, 100);
2726:   const chance = clamp(.16 + app.match / 125 + reputation / 600 + (fieldCredential ? .06 : 0), .05, .94);
2727:   app.interviewWorld = civ.worldMinutes;
2728:   if (!rng.chance(chance)) {
2729:     app.status = 'rejected';
2730:     game.player.reputation = clamp((game.player.reputation || 0) - 0.2, 0, 100);
2731:     emitPlayerFeed(game, `${job.companyName} passed on your ${job.title} application.`, 'warn');
2732:     return { ok: true, hired: false, application: app, job, chance };
2733:   }
2734:   const offer = Math.max(18000, Math.round(job.salary * clamp(.9 + app.match / 500 + rng.float(0, .08), .86, 1.26) / 100) * 100);
2735:   app.status = 'offered';
2736:   app.offerSalary = offer;
2737:   emitPlayerFeed(game, `${job.companyName} offered you ${job.title} at ${fmtMoney(offer)}/yr.`, 'good');
2738:   return { ok: true, hired: false, offered: true, application: app, job, offer, chance };
2739: }
