2741: export function playerNegotiateJob(game, query, amount) {
2742:   const civ = ensureCivilization(game);
2743:   const app = findApplication(civ, query);
2744:   if (!app || app.status !== 'offered') return { ok: false, error: 'No open offer to negotiate. Interview first.' };
2745:   const job = civ.jobs.find(j => j.id === app.jobId);
2746:   if (!job) return { ok: false, error: 'That role no longer exists.' };
2747:   const desired = Math.round(Number(amount) || 0);
2748:   if (desired <= app.offerSalary) return { ok: false, error: `Ask for more than the current offer (${fmtMoney(app.offerSalary)}).` };
2749:   if (desired > app.offerSalary * 1.4) return { ok: false, error: 'That request is too far above the posted range.' };
2750:   const rng = makeRng((game.seed ^ hash32(app.id) ^ 0x6a11 ^ game.tickCount) >>> 0);
2751:   const chance = clamp(.9 - (desired / app.offerSalary - 1) * 1.6 + app.match / 450, .12, .94);
2752:   if (rng.chance(chance)) {
2753:     app.offerSalary = desired;
2754:     emitPlayerFeed(game, `${job.companyName} raised your offer to ${fmtMoney(desired)}.`, 'good');
2755:     return { ok: true, accepted: true, application: app, job, offer: desired };
2756:   }
2757:   app.status = 'rejected';
2758:   emitPlayerFeed(game, `${job.companyName} withdrew the offer after negotiation.`, 'bad');
2759:   return { ok: true, accepted: false, application: app, job, offer: app.offerSalary };
2760: }
