2879: export function authorizeAction(game, actorId, action) {
2880:   const civ = ensureCivilization(game);
2881:   const mp = civ.multiplayer;
2882:   const actor = mp.players.find(p => p.id === actorId || p.handle === actorId);
2883:   if (!actor) return { ok: false, error: 'unknown actor' };
2884:   if (!actor.connected && action !== 'sync') return { ok: false, error: 'actor is disconnected' };
2885:   const allowed = mp.permissions[actor.role] || [];
2886:   if (!allowed.includes(action) && !allowed.includes('admin')) return { ok: false, error: `role ${actor.role} may not perform ${action}` };
2887:   const bucket = Math.floor((civ.worldMinutes || 0) / DAY);
2888:   const key = `${actor.id}:${action}:${bucket}`;
2889:   mp.antiCheat.rate[key] = (mp.antiCheat.rate[key] || 0) + 1;
2890:   for (const existing of Object.keys(mp.antiCheat.rate)) {
2891:     if (!existing.endsWith(`:${bucket}`)) delete mp.antiCheat.rate[existing];
2892:   }
2893:   if (mp.antiCheat.rate[key] > 90) {
2894:     mp.antiCheat.rejected++;
2895:     return { ok: false, error: 'rate limit exceeded' };
2896:   }
2897:   return { ok: true, actor };
2898: }
