2900: export function validateLedger(game) {
2901:   const civ = ensureCivilization(game);
2902:   const mp = civ.multiplayer;
2903:   if (!mp.ledger.length) return { ok: true, head: mp.ledgerHead || 'genesis', entries: 0, checked: 0 };
2904:   // The ledger is retention-bounded. The oldest retained row anchors the
2905:   // verifiable window; its prev hash may point at an entry already trimmed.
2906:   let prev = mp.ledger[0].prev;
2907:   for (const row of mp.ledger) {
2908:     const body = JSON.stringify({ actor: row.actor, action: row.action, amount: row.amount, memo: row.memo, world: row.world });
2909:     const expected = hash32(prev + body).toString(16).padStart(8, '0');
2910:     if (row.prev !== prev || row.hash !== expected) return { ok: false, brokenAt: row.id, expected, found: row.hash };
2911:     prev = row.hash;
2912:   }
2913:   if (mp.ledgerHead !== prev) return { ok: false, brokenAt: 'head', expected: prev, found: mp.ledgerHead };
2914:   return { ok: true, head: mp.ledgerHead, entries: mp.ledger.length, checked: mp.ledger.length };
2915: }
