2917: export function joinSharedWorld(game, profile = {}) {
2918:   const civ = ensureCivilization(game);
2919:   const mp = civ.multiplayer;
2920:   const id = profile.id || `remote-${hash32(`${profile.handle || ''}:${Date.now()}`).toString(16).slice(0, 8)}`;
2921:   let player = mp.players.find(p => p.id === id || p.handle === profile.handle);
2922:   if (!player) {
2923:     player = { id, handle: profile.handle || 'remote-operator', name: profile.name || 'Remote Operator', role: profile.role || 'operator', connected: true, lastSeen: Date.now(), permissions: [...(mp.permissions[profile.role || 'operator'] || [])] };
2924:     mp.players.push(player);
2925:   } else {
