3813:   const row = { id: nextId(civ, 'ledger'), seq: mp.ledger.length + 1, actor: entry.actor || 'player', action: entry.action || 'unknown', amount: Math.round(entry.amount || 0), memo: entry.memo || '', world: civ.worldMinutes, prev, hash, at: Date.now() };
3814:   mp.ledger.push(row);
