3820: export function authorizeAction(game, actorId, action) {
3821:   const civ = ensureCivilization(game);
3822:   const mp = civ.multiplayer;
3823:   const actor = mp.players.find(p => p.id === actorId || p.handle === actorId);
3824:   if (!actor) return { ok: false, error: 'unknown actor' };
3825:   if (!actor.connected && action !== 'sync') return { ok: false, error: 'actor is disconnected' };
3826:   const allowed = mp.permissions[actor.role] || [];
3827:   if (!allowed.includes(action) && !allowed.includes('admin')) return { ok: false, error: `role ${actor.role} may not perform ${action}` };
3828:   const bucket = Math.floor((civ.worldMinutes || 0) / DAY);
3829:   const key = `${actor.id}:${action}:${bucket}`;
3830:   mp.antiCheat.rate[key] = (mp.antiCheat.rate[key] || 0) + 1;
3831:   for (const existing of Object.keys(mp.antiCheat.rate)) {
3832:     if (!existing.endsWith(`:${bucket}`)) delete mp.antiCheat.rate[existing];
3833:   }
3834:   if (mp.antiCheat.rate[key] > 90) {
3835:     mp.antiCheat.rejected++;
3836:     return { ok: false, error: 'rate limit exceeded' };
3837:   }
3838:   return { ok: true, actor };
3839: }
