3841: export function validateLedger(game) {
3842:   const civ = ensureCivilization(game);
3843:   const mp = civ.multiplayer;
3844:   if (!mp.ledger.length) return { ok: true, head: mp.ledgerHead || 'genesis', entries: 0, checked: 0 };
3845:   // The ledger is retention-bounded. The oldest retained row anchors the
3846:   // verifiable window; its prev hash may point at an entry already trimmed.
3847:   let prev = mp.ledger[0].prev;
3848:   for (const row of mp.ledger) {
3849:     const body = JSON.stringify({ actor: row.actor, action: row.action, amount: row.amount, memo: row.memo, world: row.world });
3850:     const expected = hash32(prev + body).toString(16).padStart(8, '0');
3851:     if (row.prev !== prev || row.hash !== expected) return { ok: false, brokenAt: row.id, expected, found: row.hash };
3852:     prev = row.hash;
3853:   }
3854:   if (mp.ledgerHead !== prev) return { ok: false, brokenAt: 'head', expected: prev, found: mp.ledgerHead };
3855:   return { ok: true, head: mp.ledgerHead, entries: mp.ledger.length, checked: mp.ledger.length };
3856: }
