3887:   const civ = ensureCivilization(game);
3888:   if (action === 'sync') {
3889:     civ.multiplayer.lastSync = Date.now();
3890:     return { ok: true, metrics: civ.metrics, snapshot: sharedSnapshot(game) };
3891:   }
3892:   if (action === 'trade' || action === 'property' || action === 'contracts' || action === 'company' || action === 'research' || action === 'publish') {
3893:     const row = recordLedger(game, { actor: auth.actor.handle, action, amount: payload.amount || 0, memo: payload.memo || action });
3894:     civ.multiplayer.lastSync = Date.now();
3895:     return { ok: true, accepted: row, authoritative: true, note: 'Action recorded. Transport adapters can relay this ledger entry to a shared server.' };
3896:   }
3897:   return { ok: false, error: `unsupported action ${action}` };
3898: }
