import assert from 'node:assert/strict';
import { createGame, tickWorld, simulateOffline, WORLD_VERSION } from '/home/runner/work/PlayGround/PlayGround/src/world.js';
import {
  CAPS, ensureCivilization, tickCivilization, playerRelease, playerBuyProperty,
  playerInsureProperty, applyRemoteAction, joinSharedWorld, validateLedger,
  civilizationSummary, playerProperties, playerSellProperty
} from '/home/runner/work/PlayGround/PlayGround/src/civilization.js';

console.log('world version', WORLD_VERSION);
const game = createGame(123456);
assert.ok(game.civ, 'civilization built at create');
const civ = ensureCivilization(game);
assert.ok(civ.society.households.length > 0, 'households exist');
assert.ok(civ.justice.professionals.length > 0, 'legal professionals exist');
assert.ok(civ.relations.blocs.length >= 0, 'blocs structure exists');

// Progress five thousand minutes in bounded chunks.
for (let i = 0; i < 100; i++) tickWorld(game, 50);
assert.ok(game.worldMinutes >= 5000);
assert.ok(civ.disputes.length > 0, 'legal caseload forms over time');
assert.ok(civ.tech.technologies.length > 0, 'technology released');
assert.ok(civ.culture.events.length > 0, 'culture events scheduled');
assert.ok(civ.society.decisions.length > 0, 'agent decisions recorded');

const caps = [
  ['companies', game.companies.length, 30], ['npcs', game.npcs.length, 420],
  ['servers', game.servers.length, 240], ['sites', game.sites.length, 220],
  ['contracts', game.contracts.length > 60 ? game.contracts.filter(c => c.status === 'open').length : game.contracts.length, 60],
  ['disputes', civ.disputes.length, CAPS.disputes], ['tech', civ.tech.technologies.length, CAPS.tech],
  ['games', civ.culture.games.length, CAPS.games], ['music', civ.culture.music.length, CAPS.music],
  ['households', civ.society.households.length, CAPS.households],
  ['decisions', civ.society.decisions.length, CAPS.decisions],
  ['negotiations', civ.relations.negotiations.length, CAPS.negotiations],
  ['ledger', civ.multiplayer.ledger.length, CAPS.ledger]
];
for (const [name, actual, cap] of caps) {
  assert.ok(actual <= cap, `${name} ${actual} exceeds cap ${cap}`);
}

// Player entertainment release.
game.player.money = 50000;
const release = playerRelease(game, 'game', 'Signal Run', { price: 15 });
assert.ok(release.ok, release.error);
assert.equal(release.work.creatorId, 'player');

// Property with mortgage and insurance.
const listing = civ.property.listings.find(p => p.status === 'available');
assert.ok(listing, 'a listing exists');
const buy = playerBuyProperty(game, listing.id, { mortgage: true, insure: true });
assert.ok(buy.ok, buy.error);
assert.ok(buy.property.mortgage, 'mortgage recorded');
assert.ok(buy.property.insurance > 0, 'insurance recorded');
const insured = playerInsureProperty(game, listing.id);
assert.ok(insured.ok && insured.already, 'insurance idempotent');
const sell = playerSellProperty(game, listing.id);
assert.ok(sell.ok && sell.payoff > 0, 'mortgage payoff on sale');

// Multiplayer authority: join, reject unexpected credential, spend and reject overdraft.
const joined = joinSharedWorld(game, { handle: 'remote-a', role: 'operator', balance: 500 });
assert.ok(joined.ok);
const good = applyRemoteAction(game, 'remote-a', 'trade', {
  amount: 100, memo: 'hardware', credential: joined.player.credential, requestId: 'req-1'
});
assert.ok(good.ok, good.error);
assert.equal(good.balance, 400);
const dup = applyRemoteAction(game, 'remote-a', 'trade', {
  amount: 100, memo: 'hardware', credential: joined.player.credential, requestId: 'req-1'
});
assert.ok(dup.ok && dup.duplicate, 'idempotent replay');
const over = applyRemoteAction(game, 'remote-a', 'trade', {
  amount: 9999, memo: 'too much', credential: joined.player.credential, requestId: 'req-2'
});
assert.ok(!over.ok, 'overdraft rejected');
const badCred = applyRemoteAction(game, 'remote-a', 'trade', {
  amount: 1, memo: 'forged', credential: 'deadbeef', requestId: 'req-3'
});
assert.ok(!badCred.ok, 'forged credential rejected');
assert.ok(validateLedger(game).ok, 'ledger valid after actions');

// Save / revive path keeps systems.
const json = JSON.parse(JSON.stringify(game));
json.version = WORLD_VERSION;
const { reviveGame } = await import('/home/runner/work/PlayGround/PlayGround/src/world.js');
const revived = reviveGame(json);
assert.ok(revived.civ.society.households.length > 0, 'households survive revive');
assert.ok(Array.isArray(revived.civ.justice.professionals), 'justice survives revive');

// Determinism over a fresh run.
const a = createGame(999);
const b = createGame(999);
for (let i = 0; i < 40; i++) { tickWorld(a, 60); tickWorld(b, 60); }
assert.equal(a.civ.metrics.civilizationIndex, b.civ.metrics.civilizationIndex);
assert.equal(a.civ.timeline.length, b.civ.timeline.length);
assert.equal(JSON.stringify(a.civ.relations.negotiations.map(n => n.id + n.status)), JSON.stringify(b.civ.relations.negotiations.map(n => n.id + n.status)));

// Offline simulation remains functional.
const before = a.worldMinutes;
simulateOffline(a, 1000 * 60 * 60 * 24 * 40);
assert.ok(a.worldMinutes > before, 'offline advances the world');
assert.ok(a.civ.society.households.length > 0);

// Long horizon: three simulated years.
const long = createGame(4242);
for (let day = 0; day < 365 * 3; day++) tickWorld(long, 1440);
assert.ok(long.civ.metrics.year >= 2029, `year advanced to ${long.civ.metrics.year}`);
assert.ok(long.npcs.length <= 420 && long.companies.length <= 30, 'progression caps hold');
assert.ok(long.civ.tech.technologies.length <= CAPS.tech);
assert.ok(long.civ.timeline.length > 20, 'history accumulates');
console.log('three-year metrics', long.civ.metrics);
console.log('caps', {
  companies: long.companies.length, npcs: long.npcs.length, servers: long.servers.length,
  sites: long.sites.length, contracts: long.contracts.length,
  households: long.civ.society.households.length, tech: long.civ.tech.technologies.length,
  timeline: long.civ.timeline.length
});
console.log('ALL CHECKS PASSED');

