/* ============================================================
   INTERNET: PERSISTENT WORLD — workstation shell
   ============================================================ */
:root{
  --bg:#080a0c;
  --bg2:#0b0e11;
  --panel:#0e1216;
  --panel2:#11161b;
  --panel3:#151b21;
  --line:#202830;
  --line2:#2b353f;
  --text:#c8d3da;
  --text2:#94a3ad;
  --dim:#65737d;
  --faint:#43505a;
  --green:#79e6a3;
  --green2:#3fb970;
  --cyan:#63c8e8;
  --blue:#6ea8fe;
  --amber:#e3b341;
  --red:#f2727d;
  --purple:#c39bf5;
  --mono:"JetBrains Mono","SFMono-Regular","Cascadia Code",Consolas,"Liberation Mono",Menlo,monospace;
  --sans:"Inter","Segoe UI",system-ui,-apple-system,Roboto,Helvetica,Arial,sans-serif;
  --radius:7px;
  --shadow:0 18px 48px rgba(0,0,0,.55),0 2px 8px rgba(0,0,0,.4);
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;background:var(--bg);color:var(--text);
  font-family:var(--sans);font-size:13px;line-height:1.45;
