.svg-sprite{position:absolute;width:0;height:0;overflow:hidden}
.ico{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;display:block;flex:0 0 auto}
.dim{color:var(--dim)}

#app{height:100dvh;display:flex;flex-direction:column;background:
