import { createGame, tickWorld } from '/home/runner/work/PlayGround/PlayGround/src/world.js';
import { execute } from '/home/runner/work/PlayGround/PlayGround/src/shell.js';

const game = createGame(2026);
game.player.money = 200000;
for (let i = 0; i < 40; i++) tickWorld(game, 1440);
const app = { game };
const term = { history: [], histIndex: 0, cwd: '/home/player', user: 'player', host: 'meridian', print() {}, write() {} };

const lines = [
  'civ', 'civ status', 'civ countries', 'civ cities', 'civ laws', 'civ legal',
  'civ identity', 'civ society', 'civ diplomacy', 'civ media', 'civ tech', 'civ supply',
  'civ property', 'civ property available', 'civ history', 'civ events',
  'civ research', 'civ jobs', 'civ career', 'civ courses',
  'civ mp', 'civ mp status', 'civ mp validate', 'civ mp snapshot',
  'civ study programming 3', 'civ research start computer-science', 'civ release game Test Runner --price 5'
];
let failures = 0;
for (const line of lines) {
  term.out = [];
  await execute(app, term, line);
  const text = term.out.map(o => o.text).join('\n');
  if (/internal simulation error|command not found/i.test(text)) {
    failures++;
    console.log(`FAIL ${line}\n${text}\n`);
  } else {
    console.log(`ok   ${line} (${term.out.length} lines)`);
  }
}
console.log(failures ? `SMOKE FAILURES ${failures}` : 'SMOKE OK');

