      } else {
        term.print('Permission denied, please try again.', 'err');
        term.print(`password:`, 'dim');
      }
    }
    return;
  }
  if (p.kind === 'confirm-reset') {
    term.pending = null;
    if (/^y(es)?$/i.test(input)) {
